(window.BUNKAZAI_DETAIL=window.BUNKAZAI_DETAIL||{})["c15"]=[{"id":"00010117","register_sub_id":"101","register_pk":"197950","name":"中村家住宅稲荷社","kana":"なかむらけじゅうたくいなりしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-3","lat":35.716697,"lng":139.940616,"geo_status":"db","era":"明治24","year":1891,"year_source":"db","year_min":1891,"year_max":1891,"year_label":null,"structure":"木造平屋建、銅板葺、建築面積0.3㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0177","desc":"敷地の南西側に位置し、江戸切仕上げの石積基壇上に東面して鎮座する。一間社流造、銅板葺で、正側面に縁高欄を廻らし、正面に木階を設ける。良質なケヤキを主材とし、水引虹梁や妻虹梁上に蟇股を飾り、妻飾に懸魚を吊る。丁寧な造作になる稲荷社である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010117"},{"id":"00010115","register_sub_id":"101","register_pk":"197948","name":"中村家住宅北蔵及び事務所","kana":"なかむらけじゅうたくきたぐらおよびじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"千葉県","address":"千葉県市川市鬼越2-200-1","lat":35.716926,"lng":139.941029,"geo_status":"db","era":"北蔵 大正後期 事務所 昭和前期","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺及び鉄板葺、建築面積55㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0175","desc":"主屋の東側に位置し、西半が木造二階建の北蔵で、その南西面に事務所を接続する。北蔵は当初より外壁鉄板張で、両妻面に窓を穿つ。事務所は洗出し仕上げで石造風に化粧目地を施し、頂部のコーニスと窓上部のアーチをアクセントとする、洋風意匠の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010115"},{"id":"00010111","register_sub_id":"101","register_pk":"197944","name":"中村家住宅主屋","kana":"なかむらけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-1他","lat":35.716947,"lng":139.940821,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積193㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0171","desc":"寄棟造桟瓦葺の住宅で、千葉街道側に北妻面を向け、東面に切妻造の玄関を構え、周囲に下屋を廻らせる。北面軒は黒漆喰塗込で蛇腹をつくり、他は出桁造とする。内部は北寄りを応接間とし、後方を座敷とする。並び建つ煉瓦蔵とともに重厚な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010111"},{"id":"00010116","register_sub_id":"101","register_pk":"197949","name":"中村家住宅倉庫","kana":"なかむらけじゅうたくそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-2","lat":35.716617,"lng":139.940833,"geo_status":"db","era":"南倉庫 明治中期／昭和前期移築 北倉庫 明治後期","year":1883,"year_source":"db","year_min":1883,"year_max":1883,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積114㎡","structure_material":"木造平屋建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0176","desc":"敷地南東側に南北棟で建つ。明治後期に建てられた北倉庫の南側に、明治中期の南倉庫を曳家して一体化したとみられ、総桁行二一メートルを測る。木造平屋建で東面に下屋を設け、小屋組はキングポストトラスとする。味噌の醸造に使用した大型倉庫である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010116"},{"id":"00010114","register_sub_id":"101","register_pk":"197947","name":"中村家住宅土蔵","kana":"なかむらけじゅうたくどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-2","lat":35.716813,"lng":139.940922,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0174","desc":"主屋と離れの間に接続し、東西棟で建つ。土蔵造二階建、切妻造桟瓦葺で、北面に下屋を設ける。北面と西面に戸口を設け、二階東面に庇付きの窓を穿つ。外壁は鉄板張で鉢巻を廻らせるが、もとは漆喰塗及び下見板張であった。屋敷構えを構成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010114"},{"id":"00010112","register_sub_id":"101","register_pk":"197945","name":"中村家住宅離れ","kana":"なかむらけじゅうたくはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-2","lat":35.71681,"lng":139.940812,"geo_status":"db","era":"明治後期／昭和中期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積75㎡","structure_material":"木造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0172","desc":"主屋南後方に接続して建つ。木造二階建、寄棟造桟瓦葺で、下屋や窓庇を設け、外壁は簓子下見板張とする。内部は上下階とも座敷飾を備えた八畳主室と六畳を並べ、一階は舟底天井の応接間を付し、二階では南東面に縁と高欄を廻らせる。落ち着いた佇まいの離れ建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010112"},{"id":"00010118","register_sub_id":"101","register_pk":"197951","name":"中村家住宅防空壕","kana":"なかむらけじゅうたくぼうくうごう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"千葉県","address":"千葉県市川市鬼越2-200-3","lat":35.716804,"lng":139.94066,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"鉄筋コンクリート造、建築面積11㎡","structure_material":"鉄筋コンクリート造","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0178","desc":"主体部は南北三・六メートル東西三メートルで、上部をヴォールト状とし、北側の前室に鍵型の通路を設けて出入口とする。壁厚三〇センチメートルの鉄筋コンクリート造で、内部に建設時の支保工を兼ねた軸組を現す。個人住宅の庭園に築造された堅牢な防空壕。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010118"},{"id":"00010119","register_sub_id":"101","register_pk":"197952","name":"中村家住宅門及び石塀","kana":"なかむらけじゅうたくもんおよびいしべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-1","lat":35.71699061,"lng":139.94097532,"geo_status":"db","era":"明治後期／昭和前期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"大門 石造、間口3.5m 車門 石造、間口3.5m 石塀 石造、総延長29m、潜戸付","structure_material":"大門 石造","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0179","desc":"敷地北面を画す石造の門塀。西寄りに主屋玄関に通じる大門、事務所横に車門を構え、折曲がりに石塀をのばす。門は二箇所とも花崗岩製で江戸切仕上げの門柱を立て、石塀は房州石を布積とし、大門脇に潜戸を吊る。重厚で高い石塀が、旧家の表構えに風格を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010119"},{"id":"00010113","register_sub_id":"101","register_pk":"197946","name":"中村家住宅煉瓦蔵","kana":"なかむらけじゅうたくれんがぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県市川市鬼越2-200-1","lat":35.717009,"lng":139.940752,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造2階建、瓦葺、建築面積20㎡","structure_material":"煉瓦造2階建","registered":"2014.10.07(平成26.10.07)","register_no":"12 － 0173","desc":"主屋西隣の敷地角地に南北棟で建つ。煉瓦造二階建、切妻造桟瓦葺で、東面を戸口とし、両妻面にアーチを付した庇窓を穿つ。壁は焼過煉瓦をイギリス積に積み、上部に雷紋風に飾るコーニスとペディメントを表す。鬼瓦の漆喰巻や高い棟積も、重厚な意匠になる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010113"},{"id":"00006519","register_sub_id":"101","register_pk":"107502","name":"宮醤油店旧米蔵","kana":"みやしょうゆてんきゅうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26181,"lng":139.88562,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積47㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0076","desc":"脇蔵の南隣に建つ。桁行５間，梁間２間半，土蔵造２階建で，平入の切妻造，桟瓦葺。小屋組はトラスの形式をとる。西側に庇を張り出し，片開塗戸の出入口を設ける。もと米蔵であるが，現在は樽を置いて醤油蔵として使用。敷地内の醸造施設の変遷を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006519"},{"id":"00006521","register_sub_id":"101","register_pk":"107504","name":"宮醤油店西蔵","kana":"みやしょうゆてんにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26172182,"lng":139.88539588,"geo_status":"db","era":"明治5","year":1872,"year_source":"db","year_min":1872,"year_max":1872,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積115㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0078","desc":"主屋の南方に中庭を介して建つ。桁行１０間半，梁間３間，土蔵造２階建，東西棟の切妻造，桟瓦葺。小屋組は和小屋。内部には木樽８つを配し，天保５年創業時のものが６つ残る。規模の大きな醤油蔵で，妻壁を白漆喰塗とした外観が敷地西辺の景観を引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006521"},{"id":"00006520","register_sub_id":"101","register_pk":"107503","name":"宮醤油店東蔵","kana":"みやしょうゆてんひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県富津市佐貫字西正石247","lat":35.26173,"lng":139.88559,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積46㎡","structure_material":"土蔵造2階建","registered":"2007.07.31(平成19.07.31)","register_no":"12 － 0077","desc":"旧米蔵の南隣に建つ。桁行５間，梁間２間半，土蔵造２階建で，平入の切妻造，桟瓦葺。小屋組はトラスの形式をとる。西側北端に出入口を設け，内部には木樽を９つ配し，諸味蔵として使用。外観は簡素なつくりであるが，中規模で，敷地の奥行を感じさせる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00006520"},{"id":"00007017","register_sub_id":"101","register_pk":"107999","name":"吉野酒造石塀","kana":"よしのしゅぞういしべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.15387115,"lng":140.24875789,"geo_status":"db","era":"明治末期・昭和初期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"東塀 石造、延長27m 西塀 石造、延長25m","structure_material":"東塀 石造","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0113","desc":"屋敷地の南辺を限る石塀で、門の両袖塀に接続。東石塀は明治末期の建設で、延長２７ｍ、地元の房州石の切石８段積で、上に笠石を置く。西石塀は昭和初期の建設で、延長２５ｍ、大谷石の切石８段積で、上に笠石を置く。道路に沿い、特色ある景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007017"},{"id":"00007010","register_sub_id":"101","register_pk":"107992","name":"吉野酒造煙突","kana":"よしのしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154076,"lng":140.248657,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"煉瓦造、高さ16m","structure_material":"煉瓦造","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0106","desc":"南酒蔵の西面南寄りに位置する煉瓦造の煙突である。南酒蔵の西下屋の煉瓦造釜場の排煙に用いた。基底部は方１．２ｍで、高さは１６ｍ。煉瓦はイギリス積とする。四隅に山形鋼を添え、丸鋼をナット締めして補強している。酒造業らしいランドマークとなる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007010"},{"id":"00007011","register_sub_id":"101","register_pk":"107993","name":"吉野酒造北酒蔵","kana":"よしのしゅぞうきたさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154415,"lng":140.248764,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積486㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0107","desc":"南酒蔵の北に建つ木造平屋建である。桁行２９ｍ梁間１６ｍの南北棟で、屋根は切妻造桟瓦葺とする。小屋組はキングポスト・トラス。切石の基礎上に建ち、外壁は真壁造白漆喰塗で、腰と妻壁を押縁下見板張とする。南酒蔵と並ぶ姿は醸造業らしい景観をなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007011"},{"id":"00007013","register_sub_id":"101","register_pk":"107995","name":"吉野酒造北土蔵","kana":"よしのしゅぞうきたどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154278,"lng":140.248337,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"土蔵造2階建、瓦葺、建築面積50㎡","structure_material":"土蔵造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0109","desc":"南蔵の北に建つ土蔵造２階建である。桁行９．１ｍ梁間５．５ｍの南北棟で、屋根は切妻造桟瓦葺とし、東面全面に瓦葺庇を付けて戸口１ヶ所を設ける。小屋組は和小屋。切石基礎上に建ち、外壁は白漆喰塗で、腰を海鼠壁とするが、下部はモルタル塗としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007013"},{"id":"00007014","register_sub_id":"101","register_pk":"107996","name":"吉野酒造旧馬屋","kana":"よしのしゅぞうきゅううまや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.1545385,"lng":140.2483165,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積60㎡","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0110","desc":"屋敷地の北西寄りに建つ木造平屋建である。桁行１１ｍ梁間５．５ｍの東西棟で、切妻造桟瓦葺とし、南正面に鉄板葺庇が付く。内部は奥から３．０ｍ位置で仕切り、桁行に３等分して馬房とする。外壁は真壁造漆喰塗で、腰と妻を押縁下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007014"},{"id":"00007008","register_sub_id":"101","register_pk":"107990","name":"吉野酒造店舗兼主屋","kana":"よしのしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154015,"lng":140.248505,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積299㎡","structure_material":"木造2階一部平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0104","desc":"道路北側の敷地南西寄りに南面して建つ木造２階建で、背面に平屋を突出する。屋根は寄棟造桟瓦葺で、瓦葺庇がまわり、正面中央に式台、その東に入母屋屋根の玄関がある。内部は東に土間、西に８畳座敷など４室を配す。出桁造の深い２階の軒が重厚な外観を呈す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007008"},{"id":"00007015","register_sub_id":"101","register_pk":"107997","name":"吉野酒造松尾神社","kana":"よしのしゅぞうまつおじんじゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.15485569,"lng":140.24887331,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造平屋建、瓦葺、建築面積10㎡、宮殿付","structure_material":"木造平屋建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0111","desc":"北酒蔵の北東に位置する。桁行３．９ｍ梁間２．１ｍの南北棟で南面する。屋根は入母屋造桟瓦葺で、正面軒は扇垂木、他は平行垂木である。正面を虹梁や蟇股で飾る。外壁は竪板壁。内部は奥から１．３ｍで床を上げ、虹梁を架けて内陣としている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007015"},{"id":"00007012","register_sub_id":"101","register_pk":"107994","name":"吉野酒造南蔵","kana":"よしのしゅぞうみなみぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.15415,"lng":140.2483185,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"木造2階建、瓦葺、建築面積58㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0108","desc":"主屋の北西に建つ木造２階建である。桁行９．１ｍ梁間６．４ｍの南北棟で、屋根は切妻造桟瓦葺とする。軒は疎垂木で、小屋組は和小屋。切石基礎上に建ち、外壁は真壁造漆喰塗で、庇下部を竪羽目板張、庇上部と妻を押縁下見板張とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007012"},{"id":"00007009","register_sub_id":"101","register_pk":"107991","name":"吉野酒造南酒蔵","kana":"よしのしゅぞうみなみさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.154099,"lng":140.24881,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積788㎡","structure_material":"木造2階建","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0105","desc":"主屋の東方に建つ木造２階建である。桁行２９ｍ梁間１０ｍの切妻造南北棟の四周に、４．５ｍから５．５ｍ幅の広い下屋を巡らせている。屋根は桟瓦葺。外壁は真壁造白漆喰塗。小屋組は梁を重ねた和小屋である。広い下屋が特徴的な外観を成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007009"},{"id":"00007016","register_sub_id":"101","register_pk":"107998","name":"吉野酒造門","kana":"よしのしゅぞうもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"千葉県","address":"千葉県勝浦市植野字腰越571他","lat":35.15385623,"lng":140.24868915,"geo_status":"db","era":"昭和30頃","year":1955,"year_source":"db","year_min":1955,"year_max":1955,"year_label":null,"structure":"石造、間口4.0m、袖塀付","structure_material":"石造","registered":"2008.04.18(平成20.04.18)","register_no":"12 － 0112","desc":"屋敷地南辺の中央に開く門。門柱は御影石の切石積で６０ｃｍ角、高さ２．４ｍで、頂部の笠石は各面の中央を縦溝で飾る。門口４．０ｍで両開の木製門扉を吊る。袖塀は切石積で壁面上部に方形の壁龕を並べ、笠石を載せ、西袖塀に潜戸が付く。敷地の正面を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007016"},{"id":"00003847","register_sub_id":"101","register_pk":"104837","name":"石川酒造新蔵","kana":"いしかわしゅぞうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.719269,"lng":139.332932,"geo_status":"db","era":"明治31／明治33増築","year":1898,"year_source":"db","year_min":1898,"year_max":1898,"year_label":null,"structure":"土蔵造2階建、鋼板葺、建築面積489㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0166","desc":"本蔵の西側，街路沿いにあり，棟札から建築年代が判る。桁行３５ｍ，梁間１３．５ｍの細長い２階建の土蔵で，屋根は一方切妻造，他方入母屋造で，置屋根式の鉄板葺とする。外壁は漆喰塗で，腰を板で覆う。本蔵とともに造り酒屋らしい景観をつくっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003847"},{"id":"00003846","register_sub_id":"101","register_pk":"104836","name":"石川酒造本蔵","kana":"いしかわしゅぞうほんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.71934394,"lng":139.33261097,"geo_status":"db","era":"明治13","year":1880,"year_source":"db","year_min":1880,"year_max":1880,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積734㎡","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0165","desc":"桁行３２ｍ，梁間２３ｍ，２階建の酒造蔵。桟瓦葺の屋根は南北棟で南面切妻造，北面入母屋造，外壁は漆喰塗，妻面に観音扉付の窓を整然と配し，内部は柱が林立した宏壮な空間である。棟札から建築年代が明確。地域景観の中で，際だった存在感を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003846"},{"id":"00003848","register_sub_id":"101","register_pk":"104838","name":"石川酒造向蔵","kana":"いしかわしゅぞうむかいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"東京都","address":"東京都福生市大字熊川字南1-1","lat":35.718731,"lng":139.332016,"geo_status":"db","era":"明治29","year":1896,"year_source":"db","year_min":1896,"year_max":1896,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積577㎡、東面付","structure_material":"土蔵造2階建","registered":"2004.02.17(平成16.02.17)","register_no":"13 － 0167","desc":"敷地西寄りにあり，棟札から建築年代が判る。南北棟の切妻造，桟瓦葺，桁行３５ｍ，梁間１３．５ｍで，２階建の土蔵造である。扉口のある東面に下屋庇，窓に小庇を付け，開口部は丁寧に鳥居型に縁取る。もと石炭小屋で，明治期の屋敷構成の有様を示している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003848"},{"id":"00011273","register_sub_id":"101","register_pk":"209109","name":"青梅織物工業協同組合旧織物加工工場","kana":"おうめおりものこうぎょうきょうどうくみあいきゅうおりものかこうこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市西分町三丁目123他","lat":35.7881,"lng":139.265465,"geo_status":"db","era":"昭和10頃／平成9・同18改修","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積715㎡","structure_material":"木造平屋建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0371","desc":"原糸を織機にかける前段階のサイジングのために建てられた工場。建築面積七一五平方メートルの大規模木造平屋建で、キングポストトラスによる四連の鉄板葺鋸屋根を連ね、北側採光とする。長手方向の壁面は下見板張。地域に残るなかでも最大規模の鋸屋根工場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011273"},{"id":"00011274","register_sub_id":"101","register_pk":"209110","name":"青梅織物工業協同組合旧発券倉庫","kana":"おうめおりものこうぎょうきょうどうくみあいきゅうはっけんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"昭和前","pref":"東京都","address":"東京都青梅市西分町三丁目127-6他","lat":35.788404,"lng":139.266366,"geo_status":"db","era":"昭和前期／平成12改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"石造2階建、瓦葺、建築面積159㎡","structure_material":"石造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"13－0372","desc":"布地等を保管していた石造倉庫。内部は一・二階とも一室とし、小屋はトラス組。屋根は切妻造桟瓦葺とする。西面に扉口を開き、その二階と南北妻面一・二階に両開き金属扉の窓を設ける。大谷石積の外観で、繊維業で栄えた往時の景観を今に伝えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011274"},{"id":"00009727","register_sub_id":"101","register_pk":"195556","name":"田村酒造石垣","kana":"たむらしゅぞういしがき","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"大正","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.74145029,"lng":139.32094568,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"石造、総延長145m","structure_material":"石造","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0312","desc":"敷地東側の玉川上水に面して築かれた石垣。総延長一四五メートルで、敷地東面から南面東寄りまで矩折れにのび、東面の中央部に出入口を設ける。河原石を腰高まで丁寧に積み上げる構造で、天端石をやや迫り出す。玉川上水に面した酒造場の景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009727"},{"id":"00009726","register_sub_id":"101","register_pk":"195555","name":"田村酒造旧水車小屋及び脇蔵","kana":"たむらしゅぞうきゅうすいしゃごやおよびわきぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和前","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.74135396,"lng":139.32074921,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造及び土蔵造平屋建、鉄板葺、建築面積104㎡","structure_material":"木造及び土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0311","desc":"敷地東面中央、玉川上水からの導水路脇に建つ。北半を木造で四間四方の水車小屋、南半を土蔵造の脇蔵とし、全体に切妻造鉄板葺の屋根をかける。いずれも外壁の腰を板壁とし、小屋組はキングポストトラスとする。水車による動力で精米を行った様子を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009726"},{"id":"00009723","register_sub_id":"101","register_pk":"195552","name":"田村酒造酒造蔵","kana":"たむらしゅぞうしゅぞうくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.7418013,"lng":139.32006392,"geo_status":"db","era":"文政5頃／大正7・大正11増築","year":1822,"year_source":"db","year_min":1822,"year_max":1822,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積912㎡、煙突付","structure_material":"土蔵造平屋建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0308","desc":"玉川上水沿いの敷地北西に建つ酒造場の中心建物で、南より切妻造の本蔵、中蔵、新蔵が連立し、本蔵南に煉瓦煙突が建つ。外壁漆喰塗で腰を下見板張とし、庇付窓を規則的に並べる。煙突は八角形平面で帯鉄補強する。酒造蔵の拡張過程を良好に伝える大規模土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009723"},{"id":"00009725","register_sub_id":"101","register_pk":"195554","name":"田村酒造雑蔵","kana":"たむらしゅぞうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.74129448,"lng":139.32008058,"geo_status":"db","era":"文久2","year":1862,"year_source":"db","year_min":1862,"year_max":1862,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積68㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0310","desc":"前蔵の南に隣接して南北棟で建つ。土蔵造二階建、桁行一〇・八メートル梁間五・三メートル、切妻造、置屋根式の桟瓦葺で、二箇所に入口を設け、小屋は和小屋を組む。江戸末期の酒造場の様子を伝える土蔵で、前蔵と棟方向を違え、敷地景観に変化を添える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009725"},{"id":"00009724","register_sub_id":"101","register_pk":"195553","name":"田村酒造前蔵","kana":"たむらしゅぞうまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"東京都","address":"東京都福生市大字福生字奈賀626-1他","lat":35.74137776,"lng":139.32008534,"geo_status":"db","era":"文政13","year":1830,"year_source":"db","year_min":1830,"year_max":1830,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積34㎡","structure_material":"土蔵造2階建","registered":"2013.12.24(平成25.12.24)","register_no":"13 － 0309","desc":"敷地南西に東西棟で建つ旧米蔵。土蔵造二階建、桁行六・三メートル梁間四・五メートル、切妻造妻入、置屋根の桟瓦葺で、二階の東正面に、窓と両開土扉を設ける。外壁は腰高に簓子下見板を張り、内部は登り梁併用の架構とする。酒造場草創期の姿を留める土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009724"},{"id":"00011903","register_sub_id":"101","register_pk":"211068","name":"旧内野醤油店稲荷社","kana":"きゅううちのしょうゆてんいなりしゃ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪602","lat":35.247736,"lng":139.14238,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、銅板葺、建築面積0.29㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0242","desc":"主屋北面の庭の石積基壇上に建つ一間社。正面入母屋造、軒唐破風付で背面寄棟造とする。正面の庇の虹梁形頭貫に華やかな絵様を彫り、獅子鼻を付す。組物は出組だが正面では枠肘木を重ねて複雑に組み上げ、軒は二軒繁垂木とする。小社ながら精緻な造りになる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011903"},{"id":"00011904","register_sub_id":"101","register_pk":"211069","name":"旧内野醤油店表塀","kana":"きゅううちのしょうゆてんおもてべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪598他","lat":35.247585,"lng":139.142239,"geo_status":"db","era":"大正12年頃","year":1923,"year_source":"db","year_min":1923,"year_max":1923,"year_label":null,"structure":"木造、鉄板葺、延長4.9m","structure_material":"木造","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0243","desc":"店舗兼主屋の西にのびて新座敷前庭を画す塀で、店舗寄りに潜戸を開く。布石積基礎上の土台に柱を立て、腕木で鉄板葺の板軒を受ける。壁は漆喰塗で各間に竪格子の欄間をあけ、腰は表側は竪板を大和張とし、庭側は竪板張目板打とする。表構えに風情を添える塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011904"},{"id":"00011902","register_sub_id":"101","register_pk":"211067","name":"旧内野醤油店工場","kana":"きゅううちのしょうゆてんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪600他","lat":35.247851,"lng":139.14238,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、鉄板葺、建築面積354㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0241","desc":"敷地の北西側に位置し、東西棟で南面に広い下屋を持つ主体部と、南北棟で敷地西辺を画す建物を矩折れに繋ぐ。いずれも木造で小屋はキングポストトラスを組む。外壁モルタル塗で要所に窓を配する。規模の大きな工場建築で、醸造施設としての構えを伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011902"},{"id":"00011901","register_sub_id":"101","register_pk":"211066","name":"旧内野醤油店穀蔵","kana":"きゅううちのしょうゆてんこくぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪604-イ他","lat":35.247647,"lng":139.14253,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造平屋建、鉄板葺、建築面積79㎡","structure_material":"木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0240","desc":"敷地東面に南北棟で建ち、桁行一〇メートル梁間四・五メートル、切妻造鉄板葺である。西面に戸口を開き広い下屋を設け、窓二所を穿つ。外壁モルタル塗で鉢巻を廻らし、腰を石張とする。内部は一室でキングポストトラスを組む。醸造所の一角を占める大型倉庫。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011901"},{"id":"00011897","register_sub_id":"101","register_pk":"211062","name":"旧内野醤油店店舗兼主屋","kana":"きゅううちのしょうゆてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪600他","lat":35.247642,"lng":139.142311,"geo_status":"db","era":"明治36年","year":1903,"year_source":"db","year_min":1903,"year_max":1903,"year_label":null,"structure":"木造2階建、鉄板葺及び瓦葺、建築面積139㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0236","desc":"旧東海道に南面し、店舗部は土蔵造として正面に下屋を設け軒蛇腹を廻らす。外壁は腰を石張、上方を海鼠壁とし、東端の店舗入口にアーチをつくる。内部は二階を中心に上質な座敷をもつ。正面窓廻りに銅板を張り、袖壁を設けるなど防火も講じ、重厚な趣をもつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011897"},{"id":"00011900","register_sub_id":"101","register_pk":"211065","name":"旧内野醤油店文庫蔵","kana":"きゅううちのしょうゆてんぶんこぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪600","lat":35.24769,"lng":139.142305,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積21㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0239","desc":"店舗兼主屋の北側に南北棟で建つ。桁行五・五メートル梁間三・九メートル、土蔵造二階建、切妻造鉄板葺で、外壁モルタル塗で鉢巻を廻らし、二階東面に窓を設ける。一階南妻面の戸口に重厚な土戸を開き、主屋廊下と連絡する。丁寧な施工になる内蔵形式の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011900"},{"id":"00011899","register_sub_id":"101","register_pk":"211064","name":"旧内野醤油店店蔵","kana":"きゅううちのしょうゆてんみせぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"神奈川県","address":"神奈川県小田原市板橋字大窪602他","lat":35.247582,"lng":139.142429,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、鉄板葺、建築面積28㎡","structure_material":"木造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"14 - 0238","desc":"店舗兼主屋の東に東西棟で建つ。桁行七・一メートル梁間三・九メートルの土蔵造で、外壁モルタル塗で鉢巻を廻らし、正面の腰を洗出し仕上とする。北面の戸口に庇を付し、南面二階の縦長窓に掛子塗戸を両開とする。店舗兼主屋と共に重厚な街路景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011899"},{"id":"00004217","register_sub_id":"101","register_pk":"105207","name":"旧横浜ゴム平塚製造所記念館","kana":"きゅうよこはまごむひらつかせいぞうしょきねんかん","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"神奈川県","address":"神奈川県平塚市浅間町1-1","lat":35.3338067,"lng":139.34768338,"geo_status":"db","era":"明治39頃","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積234㎡","structure_material":"木造平屋建","registered":"2004.07.23(平成16.07.23)","register_no":"14 － 0086","desc":"日英合弁の日本爆発物製造株式会社の支配人室として建設。木造平屋建で，ヴェランダやベイウィンドーなどが特徴。屋根は鉄板葺で，南東に塔屋を頂き，外壁はドイツ下見板張とする。創建当初の姿を良く残し，小規模ながら明治期の木造洋風建築の佳品と言える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004217"},{"id":"00001250","register_sub_id":"101","register_pk":"102240","name":"昭和電工川崎工場本事務所","kana":"しょうわでんこうかわさきこうじょうほんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"神奈川県","address":"神奈川県川崎市川崎区扇町28-1","lat":35.50493206,"lng":139.72303959,"geo_status":"db","era":"昭和6","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"鉄筋コンクリート造２階建，建築面積765㎡","structure_material":"鉄筋コンクリート造２階建","registered":"1999.08.23(平成11.08.23)","register_no":"14 － 0027","desc":"東京湾埋立株式会社が造成した扇町埋立地の北西部に位置する。ＲＣ造２階建、陸屋根の事務所建築で、正面中央に車寄を低平に突き出し、縦長の窓を並べた簡潔な外観意匠をとる。昭和初期京浜工業地帯における工場事務所建築の代表的事例のひとつ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001250"},{"id":"00015161","register_sub_id":"101","register_pk":"530585","name":"北條鉄工クレーンヤード","kana":"ほうじょうてっこうくれーんやーど","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目35-3他","lat":35.51291389,"lng":139.71188889,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨造平屋建、セメントスレート葺、建築面積1，704㎡","structure_material":"鉄骨造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0357","desc":"道路に面し、事務所及び工場群に囲まれた、重量鉄骨の製作組立などを行う工場。山形鋼をリベット接合した箱形ラチス梁及び柱を組合せ大空間をつくり、東・南面を波板鉄板張、内部に天井走行クレーンを三列収容する。工場景観の要をなす地域のランドマーク。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015161"},{"id":"00015159","register_sub_id":"101","register_pk":"530583","name":"北條鉄工原寸工場","kana":"ほうじょうてっこうげんすんこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目35-1他","lat":35.51316944,"lng":139.71193889,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄骨造3階建、セメントスレート葺、建築面積326㎡","structure_material":"鉄骨造3階建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0355","desc":"事務所奥に接続し、鉄骨の溶接及び原寸図を作成した作業棟。桁行三五メートルの鉄骨造三階建で、一階は吹放ちの溶接工場、二・三階は四周に水平窓を廻らし、採光に優れた無柱空間で、チョークなどで描く原寸図用の床が残り、昭和期の鉄骨製図を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015159"},{"id":"00015162","register_sub_id":"101","register_pk":"530586","name":"北條鉄工材料置場","kana":"ほうじょうてっこうざいりょうおきば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目34","lat":35.51343611,"lng":139.71179167,"geo_status":"db","era":"昭和46年","year":1971,"year_source":"db","year_min":1971,"year_max":1971,"year_label":null,"structure":"鉄骨造平屋建、セメントスレート葺、建築面積820㎡","structure_material":"鉄骨造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0358","desc":"事務所の北に位置する材料保管所。鉄骨造平屋建切妻造大波セメントスレート葺。ビルトＨ形鋼と高力ボルト接合がつくり出す大空間を波板鉄板で囲い、吹放しの西妻面から天井走行クレーンの桁を張り出す独特の外観。事業の発展と工場建築の技術的変遷を物語る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015162"},{"id":"00015158","register_sub_id":"101","register_pk":"530582","name":"北條鉄工事務所","kana":"ほうじょうてっこうじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目35-1他","lat":35.51310278,"lng":139.71162222,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄骨造及び鉄骨鉄筋コンクリート造3階建、鉄板葺、建築面積123㎡","structure_material":"鉄骨造及び鉄骨鉄筋コンクリート造3階建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0354","desc":"京浜工業地帯の一角に建つ鉄工所の事務所。一階は鉄骨鉄筋コンクリート造、二・三階は鉄骨造とし、三階の門型ラーメンに戦後隆盛した丸鋼のラチス梁を用いる。躯体は鋼材を自在に組合せ、外壁はモルタル洗出仕上とする。高度経済成長期の工場事務所の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015158"},{"id":"00015160","register_sub_id":"101","register_pk":"530584","name":"北條鉄工旧シャーリング・製缶及びロール工場","kana":"ほうじょうてっこうシャーリング・せいかんおよびロールこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"神奈川県","address":"神奈川県川崎市川崎区鋼管通四丁目35-3他","lat":35.513025,"lng":139.71216944,"geo_status":"db","era":"昭和37年","year":1962,"year_source":"db","year_min":1962,"year_max":1962,"year_label":null,"structure":"鉄骨造平屋建、セメントスレート葺、建築面積664㎡","structure_material":"鉄骨造平屋建","registered":"2024.12.03(令和6.12.03)","register_no":"14 - 0356","desc":"敷地東面に建つ鉄骨造の作業棟。切妻造セメントスレート葺東西棟の北に南北棟を接続。外壁波板鉄板張。かつて南半西が鉄板を切断するシャーリング工場、東が溶接を行う製缶工場、北半が曲げ加工をするロール工場とした。巨大な両開扉を吊る大規模工場。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015160"},{"id":"00007206","register_sub_id":"101","register_pk":"108188","name":"岩乃原葡萄園第一號石蔵","kana":"いわのはらぶどうえんだいいちごういしぐら","category":"産業2次","subcategory":"その他工作物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県上越市大字北方字上ノ原1223","lat":37.088078,"lng":138.35083,"geo_status":"db","era":"明治28","year":1895,"year_source":"db","year_min":1895,"year_max":1895,"year_label":null,"structure":"石造、面積93㎡、冷気隧道付","structure_material":"石造","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0307","desc":"斜面を開削し、凝灰岩切石で建設された矩形平面の石蔵で、面積９３㎡。当初２層であったが、下層が埋められ、屋根架構も取り外され、上部にＲＣ造２階建が載る。内部の山側には冷気隧道の入口アーチが開き、地下水の冷気により、醸造石蔵内の温湿度を調整する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007206"},{"id":"00013982","register_sub_id":"101","register_pk":"508242","name":"角屋社屋別館","kana":"かどやしゃおくべっかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県十日町市本町二丁目11他","lat":37.13073889,"lng":138.76039167,"geo_status":"db","era":"明治41年／昭和45年移築","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積206㎡","structure_material":"木造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0563","desc":"本町通に東面する店舗で、二階建切妻造妻入である。正面妻は梁と貫を現しで飾り、側面の軒はセガイ造とする。一階は北側の通り土間に大戸が残る。吹抜けのチャノマは積雪期には高窓から採光した。二階正面側は客用座敷とする。豪雪地の町家の特徴をよく示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013982"},{"id":"00005825","register_sub_id":"101","register_pk":"106811","name":"機那サフラン酒製造本舗土蔵","kana":"きなさふらんしゅせいぞうほんぽどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋4-6-33","lat":37.415966,"lng":138.84061239,"geo_status":"db","era":"大正末期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正末期","structure":"土蔵造2階建、瓦葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0237","desc":"サフラン酒の醸造で財をなした吉沢仁太郎が建設。桁行５間，梁間３間規模，切妻造，桟瓦葺の土蔵で，基礎は石積み，腰を海鼠壁とする。軒廻り，開口部の楣部と塗戸に，鳳凰，麒麟，恵比須，大黒や十二支などの極彩色鏝絵を施す。左官は地元の河上伊吉と伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005825"},{"id":"00013529","register_sub_id":"101","register_pk":"504893","name":"旧機那サフラン酒製造本舗石垣","kana":"きゅうきなさふらんしゅせいぞうほんぽいしがき","category":"産業2次","subcategory":"その他工作物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1他","lat":37.41579722,"lng":138.84070278,"geo_status":"db","era":"明治後期／大正11年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"石造、総延長122m","structure_material":"石造","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0542","desc":"敷地の東面、南北二箇所を出入口として開けた総延長一〇四メートルに渡る石垣と、敷地内の築山際に築かれた石垣からなる。東面の石垣は自然石を亀甲形に整形して六段に積み、上部に葛石を載せる。広大な工場の敷地を区切り、前面道路からの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013529"},{"id":"00013522","register_sub_id":"101","register_pk":"504886","name":"旧機那サフラン酒製造本舗衣装蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1","lat":37.41570278,"lng":138.84051111,"geo_status":"db","era":"大正5年","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積53㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0535","desc":"主屋前方南面に接続して建つ。東西棟で二階建切妻造桟瓦葺。内部は一、二階とも一室。正面妻の鉢巻に唐草やサフランの花弁、戸口や窓の扉内側に龍や動物等を色鮮やかな鏝絵で飾る。「鏝絵蔵」として地域に親しまれる土蔵同様、当施設を代表する建物の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013522"},{"id":"00013526","register_sub_id":"101","register_pk":"504890","name":"旧機那サフラン酒製造本舗一号倉","kana":"きゅうきなさふらんしゅせいぞうほんぽいちごうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2273-1他","lat":37.41621111,"lng":138.8405,"geo_status":"db","era":"明治中期／大正15年移築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積54㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0539","desc":"敷地の北寄りに独立して建つ。二階建切妻造桟瓦葺で東西棟とし西に下屋を差掛け戸口とする。漆喰仕上で腰を鉄板で養生し東妻には吉の字をかたどる。一、二階とも一室で、小屋は桁行中央間に梁を渡す。当地で醸造を開始して以来の遺構で、北辺の景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013526"},{"id":"00013520","register_sub_id":"101","register_pk":"504884","name":"旧機那サフラン酒製造本舗主屋","kana":"きゅうきなさふらんしゅせいぞうほんぽおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1他","lat":37.41585556,"lng":138.84045,"geo_status":"db","era":"明治中期／大正2年増築","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積469㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0533","desc":"長岡市街南方にあるサフラン酒造会社の主屋。東面し、当初の玄関と増築された主体部からなる。主体部は二階建入母屋造桟瓦葺で表に二列六室、背面に座敷及び三室を有する広大なもの。切妻造の重厚な玄関にはサフラン酒の看板を掲げて表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013520"},{"id":"00013527","register_sub_id":"101","register_pk":"504891","name":"旧機那サフラン酒製造本舗米蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目1026","lat":37.41638333,"lng":138.84039167,"geo_status":"db","era":"昭和前期／令和2年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"土蔵造平屋建、瓦葺、建築面積150㎡","structure_material":"土蔵造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0540","desc":"敷地の北方に独立して建つ。平屋建切妻造桟瓦葺で東西棟とし南に下屋を張出し戸口をつくる。下屋上部を二階窓高さで海鼠壁とし化粧とするほか東妻に漆喰で吉の字を飾る。。内部は一室で土間床とし、キングポストトラスの小屋組を現す。敷地北端の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013527"},{"id":"00013528","register_sub_id":"101","register_pk":"504892","name":"旧機那サフラン酒製造本舗シチレン蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽしちれんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目169-1","lat":37.41530278,"lng":138.83997778,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"土蔵造2階建、鉄板葺、建築面積52㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0541","desc":"敷地の南西隅に独立して建つ。東西棟で二階建切妻造の鉄板葺置屋根を前室まで葺き降ろす。腰を鉄板で養生し上部は漆喰塗。北を戸口とし内部も鉄板で覆う。当蔵で花火を製造したとの伝聞があり、湿気対策とも思われるが当時の用途は不詳。敷地の一角を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013528"},{"id":"00013524","register_sub_id":"101","register_pk":"504888","name":"旧機那サフラン酒製造本舗醸造蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目1027他","lat":37.41597222,"lng":138.84018333,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積133㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0537","desc":"主屋背面に主屋と接続して建つ。東西棟で二階建切妻造桟瓦葺とし、東面に下屋を設けて戸口を建てる。内部に四本の独立柱が立ち、直接小屋梁を受ける。一階は土間を挟んで北に資材室、南に製品置場、西を製造タンクの倉庫とした。薬酒製造に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013524"},{"id":"00013523","register_sub_id":"101","register_pk":"504887","name":"旧機那サフラン酒製造本舗調整蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽちょうせいぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1他","lat":37.41601111,"lng":138.84041944,"geo_status":"db","era":"大正15年","year":1926,"year_source":"db","year_min":1926,"year_max":1926,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積159㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0536","desc":"主屋北に接続して建つ。南北棟で二階建切妻造桟瓦葺。北に下屋を設け戸口とする。小屋は梁間六間にクイーンポストトラスを掛け渡す。一階は中廊下に西を生薬貯蔵室、調製場、東を瓶詰場等とし二階は検査室や資材庫等とする。薬酒製造に欠かせない施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013523"},{"id":"00013525","register_sub_id":"101","register_pk":"504889","name":"旧機那サフラン酒製造本舗道具蔵","kana":"きゅうきなさふらんしゅせいぞうほんぽどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目1027他","lat":37.41612778,"lng":138.84022222,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積219㎡","structure_material":"土蔵造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0538","desc":"主屋背面に醸造蔵と並んで建つ。南北棟で桁行一〇間梁間四間半と比較的規模が大きく、二階建切妻造桟瓦葺。東に大振りな下屋を張り出し戸口を建てる。内部は一、二階とも一室で、独立柱が六本立ち直接小屋梁を受け母屋を渡す。敷地西方の景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013525"},{"id":"00013521","register_sub_id":"101","register_pk":"504885","name":"旧機那サフラン酒製造本舗離れ座敷","kana":"きゅうきなさふらんしゅせいぞうほんぽはなれざしき","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和前","pref":"新潟県","address":"新潟県長岡市摂田屋四丁目2292-1他","lat":37.41569444,"lng":138.84029722,"geo_status":"db","era":"昭和6年","year":1931,"year_source":"db","year_min":1931,"year_max":1931,"year_label":null,"structure":"木造2階建、瓦葺、建築面積168㎡","structure_material":"木造2階建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0534","desc":"主屋の南奥に接続して建つ。二階建入母屋造桟瓦葺で東面に唐破風玄関をつけ、三方に庇を廻す豪壮な外観。二階のたちが高く、庭側二面をガラス戸で開放する。一階は畳廊下を通して大座敷、次の間を並べ、二階は一二畳を三室とる。接遇の場として偉容を誇る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013521"},{"id":"00011103","register_sub_id":"101","register_pk":"205210","name":"旧野澤豊五郎醸造下蔵","kana":"きゅうのざわとよごろうじょうぞうしたぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県村上市塩谷字高泉寺脇1146","lat":38.159948,"lng":139.418165,"geo_status":"db","era":"大正6","year":1917,"year_source":"db","year_min":1917,"year_max":1917,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積150㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0445","desc":"醤油蔵の東に接続して建つ味噌の仕込蔵。木造平屋建、切妻造、桟瓦葺の平入で醤油蔵側に出入口を開く。外壁は竪板張で、平側上部には窓を並べる。内部は前蔵同様に屋根まで伸びる柱を桁行方向に二列並べ胴差で固める。醸造蔵の統一した景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011103"},{"id":"00011101","register_sub_id":"101","register_pk":"205208","name":"旧野澤豊五郎醸造醤油蔵","kana":"きゅうのざわとよごろうじょうぞうしょうゆぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市塩谷字高泉寺脇1146","lat":38.160009,"lng":139.417936,"geo_status":"db","era":"明治37頃／大正6増築","year":1904,"year_source":"db","year_min":1904,"year_max":1904,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積440㎡","structure_material":"木造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0443","desc":"塩谷の集落を貫く通りから少し東に入った通りに面して建つ醤油蔵。木造平屋建、切妻造、桟瓦葺で、通りに面して梁間の大きな下見板張の妻面を見せる。内部は広い土間の大空間で、曲がり材の梁を用いた和小屋を現しとする。当地域における醸造業の営みを示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011101"},{"id":"00011102","register_sub_id":"101","register_pk":"205209","name":"旧野澤豊五郎醸造前蔵","kana":"きゅうのざわとよごろうじょうぞうまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市塩谷字高泉寺脇1146","lat":38.159838,"lng":139.417905,"geo_status":"db","era":"明治40","year":1907,"year_source":"db","year_min":1907,"year_max":1907,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積150㎡","structure_material":"土蔵造平屋建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0444","desc":"醤油蔵の南に接続して建つ醤油の仕込蔵。土蔵造平屋建、切妻造、桟瓦葺妻入で外壁を漆喰塗とし、平側上部には窓を各四所開け、南妻面にマルマスの紋を付す。内部は屋根まで伸びる柱を桁行方向に二列並べ胴差で固め、壁寄りに樽を並べ中央を通路とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011102"},{"id":"00014352","register_sub_id":"101","register_pk":"511341","name":"旧早川タンス店（越後高田樂市樂座）店舗","kana":"きゅうはやかわたんすてん（えちごたかだらくいちらくざ）てんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"新潟県","address":"新潟県上越市東本町二丁目46-1他","lat":37.11955278,"lng":138.25022778,"geo_status":"db","era":"昭和22年","year":1947,"year_source":"db","year_min":1947,"year_max":1947,"year_label":null,"structure":"木造2階建、鉄板葺、建築面積163㎡","structure_material":"木造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0575","desc":"城下町高田の材木屋が集まった町にある箪笥店。二階建、切妻造平入で軒を出桁造、一階に雁木が付く。内部は前土間とミセを設け、中央に土間と廊下を通し、両脇に居室。二階表側は２２坪もの広い加工場、箪笥を上げ下げした吹抜等、歴史的景観を伝える箪笥店。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014352"},{"id":"00007205","register_sub_id":"101","register_pk":"108187","name":"玉川堂雁木","kana":"ぎょくせんどうがんぎ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県燕市燕字西郷3064-1他","lat":37.665005,"lng":138.92952,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積12㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0306","desc":"通りに東面して建つ。桁行９．２ｍ梁間１．３ｍの建物で、招屋根の桟瓦葺とする。道路側は礎石上に柱を建て軒桁を支持。店舗側は、礎石上に土台を設け、柱を建てて鴨居と長押で固め、棟木を載せる。壁は竪板壁、小壁は漆喰仕上げ。伝統的な街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007205"},{"id":"00007204","register_sub_id":"101","register_pk":"108186","name":"玉川堂鍛金場","kana":"ぎょくせんどうたんきんじょう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県燕市燕字西郷3064-1他","lat":37.66503555,"lng":138.92921853,"geo_status":"db","era":"大正期／昭和前期増築","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"木造平屋建、瓦葺、建築面積319㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0305","desc":"主屋の西方に位置する。切妻造桟瓦葺で、桁行１２ｍ梁間７．３ｍの木造平屋建。ガラス窓を大きく取り、採光に配慮。内部は北半部が土間で火炉などを備え、南半部には畳を敷き作業場とし、西方の増築部では仕上げ工程を行う。伝統産業の作業空間をよく残す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007204"},{"id":"00007202","register_sub_id":"101","register_pk":"108184","name":"玉川堂店舗","kana":"ぎょくせんどうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県燕市燕字西郷3064-1他","lat":37.665016,"lng":138.929413,"geo_status":"db","era":"明治末期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階一部平屋建、瓦葺、建築面積128㎡","structure_material":"木造2階一部平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0303","desc":"通り西側に占める短冊状の敷地前寄りに建つ。桁行８．５ｍ梁間３．６ｍ規模の木造２階建の背面に、奥行８．２ｍの平屋建を直角に付ける。内部は北側に通り土間を設け、南に和室を配し、正面南寄りにはもとは土縁と板縁を設けた。老舗の接客空間を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007202"},{"id":"00007203","register_sub_id":"101","register_pk":"108185","name":"玉川堂土蔵","kana":"ぎょくせんどうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県燕市燕字西郷3064-1他","lat":37.66495723,"lng":138.9294009,"geo_status":"db","era":"大正期","year":1919,"year_source":"estimated","year_min":1912,"year_max":1926,"year_label":"大正期","structure":"土蔵造2階建、瓦葺、建築面積20㎡","structure_material":"土蔵造2階建","registered":"2008.07.08(平成20.07.08)","register_no":"15 － 0304","desc":"店舗の西南に軸線を違え、北を正面に建ち、蔵前を介して、店舗や主屋と繋がる。桁行５．５ｍ梁間３．６ｍ規模の土蔵造２階建、切妻造桟瓦葺の置屋根とする。外壁は白漆喰仕上げとし、掛子塗戸を出入口や窓に吊り込む。内部は壁板張で、什器等を収蔵する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007203"},{"id":"00009444","register_sub_id":"101","register_pk":"194237","name":"越のむらさき主屋","kana":"こしのむらさきしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋3-2210他","lat":37.41718145,"lng":138.84243945,"geo_status":"db","era":"明治10年頃","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積127㎡","structure_material":"木造平屋一部2階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0376","desc":"交差点に北面して建つ。木造二階建、切妻造妻入桟瓦葺で、正面に下屋を設ける。外壁は簓子下見板張で、下階出入口や上階窓にガラス戸をたてる。内部は西側の事務所の天井を吹抜けとし、東側には応接室などを配する。当地方の伝統的な住宅形態を伝える建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009444"},{"id":"00009445","register_sub_id":"101","register_pk":"194238","name":"越のむらさき土蔵","kana":"こしのむらさきどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋3-2210他","lat":37.41715052,"lng":138.84250845,"geo_status":"db","era":"明治10年","year":1877,"year_source":"db","year_min":1877,"year_max":1877,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積15㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0377","desc":"主屋の南東部に張出して付属する土蔵。土蔵造二階建、桁行四・三メートル梁間三・四メートル、切妻造、置屋根式の桟瓦葺である。外壁は漆喰塗で腰を簓子下見板張とし、窓枠や鉢巻を黒漆喰で仕上げる。醸造業が盛んな摂田屋の歴史を伝える醤油醸造所の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009445"},{"id":"00015427","register_sub_id":"101","register_pk":"533442","name":"笹祝酒造事務所棟","kana":"ささいわいしゅぞうじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西蒲区松野尾字宮林3246他","lat":37.79722222,"lng":138.87122778,"geo_status":"db","era":"明治34年頃／明治後期・大正8年増築","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"木造2階建、瓦葺、建築面積285㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0604","desc":"主屋の北隣で、街道に西面して建つ事務所棟。木造二階建桟瓦葺で通り沿いに大きな切妻と半切妻の妻面を見せて下屋を付す。一階に広い店舗、検査室、事務室などを配し、コ字形平面を呈する二階は座敷を並べ杜氏部屋などにする。酒造場の雄大な表構えをつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015427"},{"id":"00015428","register_sub_id":"101","register_pk":"533443","name":"笹祝酒造煉瓦煙突","kana":"ささいわいしゅぞうれんがえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西蒲区松野尾字宮林3246","lat":37.79713611,"lng":138.87175278,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造、高さ12m","structure_material":"煉瓦造","registered":"2025.08.06(令和7.08.06)","register_no":"15 - 0605","desc":"事務所棟の東方に建つ高さ約一二メートルの煉瓦造の煙突。六角形平面の躯体をイギリス積とし、上部の径を逓減させる。下部に迫出しを設けて雁木を付し、頂部にも蛇腹を一段を設けてアクセントとする。酒造場の特徴をよく示し、地域のランドマークとなる煙突。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015428"},{"id":"00013531","register_sub_id":"101","register_pk":"504898","name":"新日本電工株式会社妙高工場赤煉瓦建屋","kana":"しんにっぽんでんこうかぶしきがいしゃみょうこうこうじょうあかれんがたてや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県妙高市大字田口字南258-4","lat":36.87426389,"lng":138.21302778,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"煉瓦造平屋建、鉄板葺、建築面積376㎡","structure_material":"煉瓦造平屋建","registered":"2021.02.04(令和3.02.04)","register_no":"15 － 0544","desc":"妙高高原駅に近接する敷地に南面して建つ元カーバイト工場。桁行三三メートル、梁間九・六メートルの煉瓦造平屋建一部二階建で、正面妻壁に東京電化工業時代の社章を付ける。関川水系の電源開発に伴い上越で発展した電気化学工業の歴史を物語る貴重な遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013531"},{"id":"00014348","register_sub_id":"101","register_pk":"511337","name":"高野醤油味噌醸造店店舗兼主屋","kana":"たかのしょうゆみそじょうぞうてんてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"新潟県","address":"新潟県上越市北本町一丁目48-3","lat":37.11979722,"lng":138.244,"geo_status":"db","era":"昭和7年／同３０年代増築","year":1932,"year_source":"db","year_min":1932,"year_max":1932,"year_label":null,"structure":"木造２階建、鉄板葺、建築面積223㎡","structure_material":"木造２階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0571","desc":"雁木が連なる高田市街の醸造業店舗兼住居。雁木を付す東正面一階はガラス障子を建込む。内部は前土間から奥へ通り土間とし、北の茶の間は吹抜け、土間南を作業室とする。背後の井戸まで突出した屋根を土蔵の蔵前とする。雪国の伝統的な市街地建築の姿を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014348"},{"id":"00014349","register_sub_id":"101","register_pk":"511338","name":"高野醤油味噌醸造店土蔵及び作業場","kana":"たかのしょうゆみそじょうぞうてんどぞうおよびさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県上越市北本町一丁目48-3","lat":37.11979167,"lng":138.24380556,"geo_status":"db","era":"明治39年／昭和７年頃増築","year":1906,"year_source":"db","year_min":1906,"year_max":1906,"year_label":null,"structure":"土蔵造2階建、鉄板葺、建築面積103㎡","structure_material":"土蔵造2階建","registered":"2022.10.31(令和4.10.31)","register_no":"15 - 0572","desc":"醸造店主屋の背後、井戸流し場に接続する家財蔵。鞘を掛けて北側を作業場通路とした内蔵形式で、西の増築部は窯場やムロなど醸造用作業場とする。土蔵の小屋組は曲材の梁で地棟を受け登梁を掛ける。戸口は煙返しと塗戸を黒漆喰で飾り、漆塗の格子戸を建てる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00014349"},{"id":"00005996","register_sub_id":"101","register_pk":"106981","name":"高橋酒造煙突","kana":"たかはししゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県長岡市地蔵1-8-2","lat":37.45523262,"lng":138.86528642,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"煉瓦造、高さ20m","structure_material":"煉瓦造","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0236","desc":"新蔵主体部の東南隅近くに独立して建つ。１辺１．２ｍの六角形平面をもつ煉瓦造煙突で，高さは約２０ｍ。頂部近くには煉瓦を持ち出して装飾的なリングを廻し，出隅には役物の鼻黒煉瓦を用いるなど丁寧なつくりで，地域のシンボルにもなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005996"},{"id":"00005952","register_sub_id":"101","register_pk":"106937","name":"高橋酒造新蔵","kana":"たかはししゅぞうしんぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"新潟県","address":"新潟県長岡市地蔵1-8-2","lat":37.455418,"lng":138.865128,"geo_status":"db","era":"大正11頃","year":1922,"year_source":"db","year_min":1922,"year_max":1922,"year_label":null,"structure":"木骨煉瓦造3階建、瓦葺、建築面積1278㎡","structure_material":"木骨煉瓦造3階建","registered":"2006.11.29(平成18.11.29)","register_no":"15 － 0235","desc":"主体部は桁行３０ｍ，梁間１８ｍ規模，東西棟，切妻造，桟瓦葺，木骨煉瓦造３階建の酒蔵で，東面に越屋根を上げた釜場が取り付き，周囲に下屋を回した大規模で複雑なつくり。長大でたちの高い赤煉瓦の外観は栖吉川左岸にあって際立った存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005952"},{"id":"00011104","register_sub_id":"101","register_pk":"205211","name":"野澤食品工業株式会社店舗兼主屋","kana":"のざわしょくひんこうぎょうかぶしきがいしゃてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市塩谷字上町1227","lat":38.156933,"lng":139.415014,"geo_status":"db","era":"明治4","year":1871,"year_source":"db","year_min":1871,"year_max":1871,"year_label":null,"structure":"木造平屋一部2階建、瓦葺、建築面積216㎡","structure_material":"木造平屋一部2階建","registered":"2016.08.01(平成28.08.01)","register_no":"15 - 0446","desc":"塩屋集落の通りに西面して建つ。木造二階建切妻造桟瓦葺で、妻面を通りに向け正面に下屋を付しせがいで軒を支えるなど当地域の特徴を良く示す。内部は南を通り土間とし二列三室に部屋を並べ、前列に帳場と床、違棚付きの奥座敷を置くなど、店舗の特徴を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011104"},{"id":"00009446","register_sub_id":"101","register_pk":"194239","name":"長谷川酒造主屋","kana":"はせがわしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋2-1831-1","lat":37.41248966,"lng":138.84491458,"geo_status":"db","era":"明治19年／大正13年改修","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積185㎡","structure_material":"木造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0378","desc":"酒造施設の南端に位置する。木造二階建、切妻造桟瓦葺で、東正面北寄りに切妻造のツメバを突出す。床上部は田字形四室で南面の庭側を座敷とする。外壁は簓子下見板張で上部漆喰塗とし、妻壁に二重の梁組を表すなど、風格ある構えを見せる老舗造酒屋の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009446"},{"id":"00001576","register_sub_id":"101","register_pk":"102566","name":"樋木酒造店舗兼主屋","kana":"ひきしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県新潟市西区内野町582","lat":37.85754724,"lng":138.93876607,"geo_status":"db","era":"明治末期／昭和30移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治末期","structure":"木造2階建、瓦葺、建築面積340㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0048","desc":"樋木酒造は天保７年，西蒲原郡巻町前田に創業したが，安政年間に現在の新潟市西部に移ったと伝える。主屋は昭和３０年に新津市柄目木の民家を移築した。前面右端に店舗を設けるが，大型の寄棟造・桟瓦葺の民家で，当地方の六間取平面をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001576"},{"id":"00001577","register_sub_id":"101","register_pk":"102567","name":"樋木酒造西酒蔵","kana":"ひきしゅぞうにしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市西区内野町582","lat":37.85778887,"lng":138.93844845,"geo_status":"db","era":"明治26","year":1893,"year_source":"db","year_min":1893,"year_max":1893,"year_label":null,"structure":"木造2階建、瓦葺、建築面積183㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0049","desc":"樋木酒造は南北に長い敷地を持ち，南正面に建つ主屋の奥に，仕込蔵などの酒造施設が並ぶ。南北に細長い切妻造・桟瓦葺の西酒蔵は明治２６年の建築である。外壁を漆喰塗と腰縦板張とし，内部は一階が貯蔵庫，二階が作業場になる伝統的な酒造蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001577"},{"id":"00001578","register_sub_id":"101","register_pk":"102568","name":"樋木酒造東酒蔵","kana":"ひきしゅぞうひがしさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県新潟市西区内野町582","lat":37.85792035,"lng":138.93873196,"geo_status":"db","era":"明治45","year":1912,"year_source":"db","year_min":1912,"year_max":1912,"year_label":null,"structure":"木造2階建、瓦葺、建築面積280㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"15 － 0050","desc":"敷地東の東酒蔵は，南北棟・切妻造・桟瓦葺で西酒蔵とほぼ同形式であるが，ひとまわり大きく，東面に２間下屋庇の増設がある。明治４５年の建築で，小屋組は杉丸太の陸梁を用いたキングポストトラスとする。近代工法を取り入れた大規模な酒造蔵である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001578"},{"id":"00001333","register_sub_id":"101","register_pk":"102323","name":"平田大六家住宅煙突","kana":"ひらただいろくけじゅうたくえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10400545,"lng":139.55063766,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦積み、1.2m四方、高さ3.6m","structure_material":"煉瓦積み","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0039","desc":"主屋と酒母蔵に挟まれた位置に建ち，もとはここに洗米，蒸米，酒しぼりなどを行う建物があった。羊羹を用いたイギリス積み煉瓦造煙突で，高さ約３．６ｍ。現在は屋敷の一点景となっているが，酒造業を営んだ当時の様相を知る上で，欠かせない構成要素である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001333"},{"id":"00001331","register_sub_id":"101","register_pk":"102321","name":"平田大六家住宅酒蔵","kana":"ひらただいろくけじゅうたくさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10417824,"lng":139.55056476,"geo_status":"db","era":"弘化2／明治初期頃増築","year":1845,"year_source":"db","year_min":1845,"year_max":1845,"year_label":null,"structure":"土蔵造平屋建一部2階建、瓦葺、建築面積119㎡","structure_material":"土蔵造平屋建一部2階建","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0037","desc":"主屋の真北に並行して建つ。桁行９間・梁間４間の東西棟の建物であるが，東側５間分が棟札より弘化２年の建築，西側４間分は明治初期頃の増築とされる。酒造業を営んでいた時期，酒を仕込み貯蔵する施設で，内部梁間２間分には２階床組が設けられている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001331"},{"id":"00001330","register_sub_id":"101","register_pk":"102320","name":"平田大六家住宅酒母蔵","kana":"ひらただいろくけじゅうたくもとぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県岩船郡関川村小見237","lat":38.10411238,"lng":139.55073262,"geo_status":"db","era":"明治初期以前","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積54㎡","structure_material":"土蔵造平屋建","registered":"1999.10.14(平成11.10.14)","register_no":"15 － 0036","desc":"屋敷地の北，主屋の北東に建つ。桁行６間半・梁間２間の細長平面で，酒造業を営んでいた時期，酒母を仕込み育成する施設として使われていた。荒壁仕上げの外壁を保護するため，周囲を縦板壁で囲んだ外観は，特色ある意匠として景観になじんでいる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001330"},{"id":"00002760","register_sub_id":"101","register_pk":"103750","name":"星名家住宅雪穴","kana":"ほしなけじゅうたくゆきあな","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"江戸","pref":"新潟県","address":"新潟県十日町市上野甲822-3","lat":37.179237,"lng":138.749985,"geo_status":"db","era":"江戸期","year":1735,"year_source":"estimated","year_min":1615,"year_max":1867,"year_label":"江戸期","structure":"石造、面積36㎡、深さ3m","structure_material":"石造","registered":"2002.06.25(平成14.06.25)","register_no":"15 － 0117","desc":"市東部，国道２５２号に隣接する雑木林の中にある石造構造物。雪季の積雪を保存し，主に酒造関連の冷蔵所として利用された。法面勾配３分程の玉石乱積壁面を一辺５ｍ程の正方形平面に築き，西壁面に階段を付ける。かつての酒造システムを今に伝える遺構。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002760"},{"id":"00009447","register_sub_id":"101","register_pk":"194240","name":"星野本店三階蔵","kana":"ほしのほんてんさんかいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋2-1812-1他","lat":37.41314639,"lng":138.84438158,"geo_status":"db","era":"明治15年／大正期増築・平成20年改修","year":1882,"year_source":"db","year_min":1882,"year_max":1882,"year_label":null,"structure":"土蔵造3階建、瓦葺、建築面積59㎡","structure_material":"土蔵造3階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0379","desc":"敷地南端に北面し、土蔵造三階建、桁行八・二メートル梁間四・六メートル、切妻造桟瓦葺である。一階正面に蔵前を設け、外壁漆喰塗で腰を簓子下見板張とする。三階は大正期の増築で、小屋はキングポストトラスを組む。特徴的な外観をもつ、醤油醸造所の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009447"},{"id":"00009448","register_sub_id":"101","register_pk":"194241","name":"星六土蔵","kana":"ほしろくどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県長岡市摂田屋4-2340-1","lat":37.41487374,"lng":138.84084512,"geo_status":"db","era":"明治中期／明治後期移築・大正7年曳家","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、鉄板葺、建築面積57㎡","structure_material":"土蔵造2階建","registered":"2013.03.29(平成25.03.29)","register_no":"15 － 0380","desc":"店舗兼主屋の南東側に接続する。土蔵造二階建、桁行七・三メートル梁間七・九メートル、切妻造、置屋根式の鉄板葺である。外壁は漆喰塗で腰を簓子下見板張とし、軒蛇腹や窓枠の一部を黒漆喰塗としてアクセントとする。星野本店から移築した味噌醸造用の土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009448"},{"id":"00003079","register_sub_id":"101","register_pk":"104069","name":"益甚酒店主屋及び酒蔵","kana":"ますじんさけてんしゅおくおよびさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県村上市大町194","lat":38.22414475,"lng":139.47890762,"geo_status":"db","era":"明治25","year":1892,"year_source":"db","year_min":1892,"year_max":1892,"year_label":null,"structure":"木造2階建、瓦葺、建築面積386㎡","structure_material":"木造2階建","registered":"2003.01.31(平成15.01.31)","register_no":"15 － 0140","desc":"店舗奥１２畳間の東方に続く主屋と，その東方に建つ酒造場及び北方の麹室から成る。主屋は棟札から棟梁は稲垣源太郎で，明治２５年の大火直後の建築であることが知られる。店舗脇から望見される間口９間半の西妻面は大火後大町の復興景観の一端を今に伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003079"},{"id":"00013980","register_sub_id":"101","register_pk":"508240","name":"山重仲町通店店舗（旧加茂錦酒造主屋）","kana":"やまじゅうなかまちとおりてんてんぽ（きゅうかもにしきしゅぞうおもや）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"新潟県","address":"新潟県加茂市仲町669-1他","lat":37.65750833,"lng":139.055275,"geo_status":"db","era":"昭和5年／平成20年改修","year":1930,"year_source":"db","year_min":1930,"year_max":1930,"year_label":null,"structure":"木造二階建、瓦葺一部鉄板葺、建築面積215㎡","structure_material":"木造二階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0561","desc":"もと造り酒屋の住宅として建築された。道路に近い北寄りが切妻造の平屋建、南が寄棟造の二階建で一連の土間が南北に貫く。平屋の一〇畳二室は小壁が高く西の土間から採光する近代的な造作で、二階座敷は端正な書院座敷である。近代の上質な市街地住宅である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013980"},{"id":"00013981","register_sub_id":"101","register_pk":"508241","name":"山重山の蔵（旧加茂錦酒造酒蔵）","kana":"やまじゅうやまのくら（きゅうかもにしきしゅぞうさかぐら）","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"新潟県","address":"新潟県加茂市仲町669-1他","lat":37.65753889,"lng":139.05521667,"geo_status":"db","era":"明治後期／平成20年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"土蔵造2階建、瓦葺、建築面積178㎡","structure_material":"土蔵造2階建","registered":"2021.10.14(令和3.10.14)","register_no":"15 - 0562","desc":"もと造り酒屋の醸造蔵で旧主屋の南に接続する南北棟。桁行二〇メートルに及ぶ土蔵造二階建で、置屋根を切妻造桟瓦葺とする。外壁は鉢巻付の漆喰塗とし、腰を竪板張とする。妻入で引分けの塗戸を備え、内部は一室、二階は酒造用の床で仕込蔵の特徴を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013981"},{"id":"00013984","register_sub_id":"101","register_pk":"508244","name":"旧藺製品作業場","kana":"きゅういせいひんさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和中","pref":"富山県","address":"富山県氷見市朝日本町907-7","lat":36.85303056,"lng":136.985925,"geo_status":"db","era":"昭和32年／同中期、平成29年改修","year":1957,"year_source":"db","year_min":1957,"year_max":1957,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積86㎡","structure_material":"木造2階一部平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0156","desc":"湊川沿いの旧藺製品倉庫の西側に建つ作業場。道路に西面して建つ木造二階建、切妻造桟瓦葺妻入で、外壁を下見板張とし、西面に戸口と換気口を設ける。内部は一階に一室、二階に二室を設け、一階を旧藺製品倉庫戸前と接続する。藺製品製造の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013984"},{"id":"00013983","register_sub_id":"101","register_pk":"508243","name":"旧藺製品倉庫","kana":"きゅういせいひんそうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県氷見市朝日本町907-7","lat":36.85297222,"lng":136.98615278,"geo_status":"db","era":"大正後期／昭和中期、平成29年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造平屋建、瓦葺、建築面積192㎡","structure_material":"土蔵造平屋建","registered":"2021.10.14(令和3.10.14)","register_no":"16 - 0155","desc":"氷見市街地の湊川左岸に建つ南面平入の東西棟。土蔵造もと二階建、切妻造桟瓦葺で、南面に戸前を設けて東端に川からの荷揚口を設ける。川に面した東面を下見板張とし、北面に額縁付の窓を穿つ。内部は一室で、独立柱で棟を支える。湊川水運の繁栄を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013983"},{"id":"00002375","register_sub_id":"101","register_pk":"103365","name":"旧南部鋳造所煙突","kana":"きゅうなんぶちゅうぞうしょえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"大正","pref":"富山県","address":"富山県高岡市金屋本町3-45","lat":36.75199236,"lng":137.0068573,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"煉瓦造、高さ15m","structure_material":"煉瓦造","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0061","desc":"炉の約７ｍ南方の地点，石造煙道の南端に接して建つ。基部の平面は１．７８ｍ角で，高さは１４．５ｍ。煉瓦造，イギリス積で，アングル材等で補強され，基部上と頭部に装飾的な帯状部を設ける。高岡鋳物の近代を物語るシンボルとして親しまれている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002375"},{"id":"00002374","register_sub_id":"101","register_pk":"103364","name":"旧南部鋳造所キュポラ","kana":"きゅうなんぶちゅうぞうしょきゅぽら","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"富山県","address":"富山県高岡市金屋本町3-45","lat":36.7520445,"lng":137.00689173,"geo_status":"db","era":"大正13","year":1924,"year_source":"db","year_min":1924,"year_max":1924,"year_label":null,"structure":"鉄製キュポラ及び煉瓦・石造煙道よりなる、鉄製吸気管付","structure_material":"鉄製キュポラ及び煉瓦・石造煙道よりなる","registered":"2001.10.12(平成13.10.12)","register_no":"16 － 0060","desc":"高岡鋳物発祥地である金屋町の一画に所在。高３．３ｍの鉄製炉，１．５ｍ角・高２．５ｍの角形煙道と０．６ｍ×１．３ｍ断面，長５．６ｍの石造煙道から成る。熱効率を高めるよう石造煙道内には送風鉄管が配置されおり，キューポラ改良の跡が認められる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002374"},{"id":"00013090","register_sub_id":"101","register_pk":"368258","name":"旧伏木港右岸三号岸壁水平引込式クレーン","kana":"きゅうふしきこううがんさんごうがんぺきすいへいひきこみしきくれーん","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"昭和後","pref":"富山県","address":"富山県射水市庄西町二丁目2573","lat":36.79159722,"lng":137.06455833,"geo_status":"db","era":"昭和43年","year":1968,"year_source":"db","year_min":1968,"year_max":1968,"year_label":null,"structure":"鉄骨造、高さ43m","structure_material":"鉄骨造","registered":"2019.12.05(令和1.12.05)","register_no":"16 － 0152","desc":"伏木港右岸に設置されたバラ物貨物荷役用クレーン。軌道上移動型のダブルリンク式の水平引込み式で、最大旋回半径三一・五メートル、吊上げ荷重八トン、全揚程二五メートルを測る。設置当時、日本海沿岸最大規模であった、伏木港のシンボル的存在。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013090"},{"id":"00008112","register_sub_id":"101","register_pk":"132510","name":"旧宮崎酒造衣装蔵","kana":"きゅうみやざきしゅぞういしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1860-1他","lat":36.76327655,"lng":137.33520046,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造3階建、瓦葺、建築面積49㎡","structure_material":"土蔵造3階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0089","desc":"中庭を介して主屋の北、酒蔵の東に位置する。桁行９．６ｍ梁間５．９ｍの３階建土蔵、東西棟の切妻造桟瓦葺で、正面に深い庇を出し、戸前とする。掛子塗の両開扉には鏝による家紋を飾り、開口上部に鳥居状のまぐさを有す。酒蔵等とともに重厚な敷地景観をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008112"},{"id":"00008111","register_sub_id":"101","register_pk":"132509","name":"旧宮崎酒造麹蔵","kana":"きゅうみやざきしゅぞうこうじぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1860-1他","lat":36.76308917,"lng":137.33513666,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積40㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0088","desc":"酒蔵と正面を並べて建つ。桁行８．２ｍ梁間５．４ｍの土蔵造２階建。酒蔵の屋根を葺き下ろし、置屋根とする。正面は１階に掛子塗の両開を吊り、扉内側に家紋をあしらい、２階に窓二ヶ所を穿ち、片開の掛子塗戸を装置するなど、存在感のある外観構成とする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008111"},{"id":"00008110","register_sub_id":"101","register_pk":"132508","name":"旧宮崎酒造酒蔵","kana":"きゅうみやざきしゅぞうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"富山県","address":"富山県滑川市瀬羽町1860-1他","lat":36.76323194,"lng":137.33498051,"geo_status":"db","era":"明治中期／昭和40年頃改修","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"土蔵造2階建、瓦葺、建築面積277㎡","structure_material":"土蔵造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0087","desc":"南北に長い短冊状の敷地北端に位置する。起りのある切妻造桟瓦葺で、Ｌ字形平面になる土蔵造２階建、建築面積２７７㎡。南妻面２階外壁を焼杉板張とし、深い庇を架けて戸前とする。外壁は漆喰壁で、正面腰壁を黒漆喰仕上げとするなど重厚な佇まいをなす。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008110"},{"id":"00008109","register_sub_id":"101","register_pk":"132507","name":"旧宮崎酒造店舗兼主屋","kana":"きゅうみやざきしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"富山県","address":"富山県滑川市瀬羽町1860-1他","lat":36.76304678,"lng":137.335341,"geo_status":"db","era":"江戸末期／明治前期・昭和前期・平成21年改修","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造2階建、瓦葺、建築面積376㎡","structure_material":"木造2階建","registered":"2010.04.28(平成22.04.28)","register_no":"16 － 0086","desc":"旧北陸街道に南面してたつ、間口１４ｍの平入町家。木造２階建、東西棟の切妻造桟瓦葺で、正面に下屋や庇を付ける。西にトオリニワ、東にミセや座敷などを二列に配し、ワクノウチと称する架構をオエなどに残す。当地域における大規模な商家の特徴をよく備える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008109"},{"id":"00015435","register_sub_id":"101","register_pk":"533450","name":"三郎丸蒸留所","kana":"さぶろうまるじょうりゅうじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"富山県","address":"富山県砺波市三郎丸字川田島188-1他","lat":36.65671944,"lng":136.97011944,"geo_status":"db","era":"昭和前期／昭和29年頃移築、平成29年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造2階建、瓦葺、建築面積803㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"16 - 0177","desc":"敷地の西北に建つ蒸留施設。桁行三六メートル、梁間二二メートルの木造二階建切妻造、外壁モルタル吹付とする。棟の中央に越屋根を設け、各階連続窓とし、内部はキングポスト・トラスを現す。工場建築を転用し、戦後に開業した北陸最古のウイスキー蒸留施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015435"},{"id":"00002032","register_sub_id":"101","register_pk":"103022","name":"城端織物組合事務棟","kana":"じょうはなおりものくみあいじむとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"昭和前","pref":"富山県","address":"富山県南砺市城端648-1","lat":36.51427262,"lng":136.90290916,"geo_status":"db","era":"昭和3","year":1928,"year_source":"db","year_min":1928,"year_max":1928,"year_label":null,"structure":"木造2階建、瓦葺、建築面積274㎡","structure_material":"木造2階建","registered":"2000.12.04(平成12.12.04)","register_no":"16 － 0059","desc":"城端は近世より絹織物を主産業とし，近代には著しく発展した。この建物は組合事務や出荷のための検査及び乾燥を目的として建てられた。木造・総２階建だが，木骨モルタル・タイル貼で煉瓦造風とした正面は，地方における洋風意匠の一端を物語っている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002032"},{"id":"00016660","register_sub_id":"101","register_pk":"579144","name":"若鶴酒造昭和蔵鶴庫","kana":"わかつるしゅぞうしょうわぐらつるこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和後","pref":"富山県","address":"富山県砺波市三郎丸字川田島207-1他","lat":36.655768,"lng":136.969364,"geo_status":"db","era":"昭和48年","year":1973,"year_source":"db","year_min":1973,"year_max":1973,"year_label":null,"structure":"鉄筋コンクリート造3階建、建築面積587㎡、屋上塔屋付","structure_material":"鉄筋コンクリート造3階建","registered":"2026.07.09(令和8.07.09)","register_no":"16 - 0179","desc":"ＪＲ油田駅西側の広大な敷地に昭和蔵松庫と並び東面して建つ醸造施設。三階建鉄筋コンクリート造のラーメン構造で柱形を外に現す。内部は階高が高い大空間で一・二階は仕込・貯蔵用の樽、三階に糀室などを配する。清酒需要の増大に対応した大規模な醸造施設。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00016660"},{"id":"00015434","register_sub_id":"101","register_pk":"533449","name":"若鶴酒造昭和蔵松庫","kana":"わかつるしゅぞうしょうわぐらまつこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"富山県","address":"富山県砺波市三郎丸字六反島401-2他","lat":36.65596667,"lng":136.96959167,"geo_status":"db","era":"昭和34年","year":1959,"year_source":"db","year_min":1959,"year_max":1959,"year_label":null,"structure":"鉄筋コンクリート造2階建、建築面積692㎡、塔屋付","structure_material":"鉄筋コンクリート造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"16 - 0176","desc":"大正蔵の北方に位置する醸造施設。二階建鉄筋コンクリート造のラーメン構造で、柱形を外に現す。内部は各階大空間で、一階は仕込庫や貯蔵庫、二階は麹室や酒母室を配する。戦後の清酒需要の増大に対応した近代的な醸造施設で、二本の塔屋が外観を印象づける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015434"},{"id":"00015433","register_sub_id":"101","register_pk":"533448","name":"若鶴酒造大正蔵","kana":"わかつるしゅぞうたいしょうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"富山県","address":"富山県砺波市三郎丸字川田島188-1他","lat":36.65530556,"lng":136.96931389,"geo_status":"db","era":"大正9年／昭和34年増築・平成7年・同24年改修","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積754㎡","structure_material":"土蔵造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"16 - 0175","desc":"ＪＲ城端線油田駅西側の広大な敷地の南西角に建つ旧醸造蔵。桁行三三メートル、梁間１１メートルの東西に下屋を付し、全体に桟瓦葺屋根を葺降ろす大規模な土蔵。外壁漆喰塗、腰竪板張。二段の額縁を廻らす小庇付の窓の連続が、印象的な歴史的景観を創出する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015433"},{"id":"00010281","register_sub_id":"101","register_pk":"199054","name":"大崎家住宅主屋","kana":"おおさきけじゅうたくしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県輪島市鳳至町上町28","lat":37.396301,"lng":136.897243,"geo_status":"db","era":"昭和4年頃","year":1929,"year_source":"db","year_min":1929,"year_max":1929,"year_label":null,"structure":"木造2階建、瓦葺、建築面積128㎡","structure_material":"木造2階建","registered":"2014.12.19(平成26.12.19)","register_no":"17-0248","desc":"通りに東面し、正面に下屋を設け、下階に格子、上階にガラス窓をたてる。南端に、後方の塗蔵に続く幅一間の土間を通し、北側に居室を二列並べる。居室の北列に中庭を設けて採光し、二階に瀟洒な座敷を配して接客に供する。輪島塗の塗師住宅の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010281"},{"id":"00011940","register_sub_id":"101","register_pk":"211088","name":"小山屋醤油店表土蔵","kana":"おやまやしょうゆてんおもてどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市相生町41-1","lat":37.04464,"lng":136.96608,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積36㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"17-274","desc":"通りに面して店舗の西に接続する。桁行四間、梁間三間、切妻造、桟瓦葺で、店舗側妻面の扉口に観音扉を開き、内格子戸を片引きで建て込む。内部は一、二階とも一室である。外壁は二階軒下まで板張とし、建ちの高い土蔵で、通りからの景観形成に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011940"},{"id":"00011942","register_sub_id":"101","register_pk":"211090","name":"小山屋醤油店醤油蔵","kana":"おやまやしょうゆてんしょうゆくら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県七尾市相生町41-1","lat":37.044454,"lng":136.966075,"geo_status":"db","era":"明治前期／平成19年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積142㎡","structure_material":"土蔵造2階建","registered":"2017.10.27(平成29.10.27)","register_no":"17-276","desc":"敷地南東隅に建つ醤油蔵。桁行六間、梁間七間、切妻造、妻入で、西半の小屋組の棟木に登梁を載せて大屋根を架ける。外壁は軒下まで下見板張とし、鉢巻を廻らし、軒出は小さい。窓を連続して穿ち、敷地後方において堂々たる外観を持つ大型の醤油蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011942"},{"id":"00011939","register_sub_id":"101","register_pk":"211087","name":"小山屋醤油店店舗兼主屋","kana":"おやまやしょうゆてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県七尾市相生町41-1","lat":37.044598,"lng":136.966158,"geo_status":"db","era":"明治後期／昭和後期改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階一部平屋建、瓦葺、建築面積290㎡","structure_material":"木造2階一部平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"17-273","desc":"七尾市中心部で通りに北面する。間口七間、奥行三間の店舗は二階建で正面に奥行一間の下屋を付す。中央の通り土間を挟み、東に作業場、西奥に居室を設ける。正面は土戸を納める戸袋や軒裏を塗込め、二階軒裏は歯飾り状の洋風意匠を見せる、特徴的な外観である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011939"},{"id":"00011941","register_sub_id":"101","register_pk":"211089","name":"小山屋醤油店ムロ","kana":"おやまやしょうゆてんむろ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県七尾市相生町41-1","lat":37.044586,"lng":136.966053,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"煉瓦造及び木造平屋建、瓦葺、建築面積44㎡","structure_material":"煉瓦造及び木造平屋建","registered":"2017.10.27(平成29.10.27)","register_no":"17-275","desc":"敷地西に表土蔵と直行して建つ。ムロは桁行一〇メートル、梁間三・一メートルの細長い平面で壁を煉瓦で積み、板天井を張り、南側に木造の前室を付け、それぞれ切妻造、桟瓦葺の屋根を架ける。二度の大火を経た七尾市において防火を意識して建てられたムロ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011941"},{"id":"00009264","register_sub_id":"101","register_pk":"194057","name":"金沢市民芸術村事務所棟","kana":"かなざわしみんげいじゅつむらじむしょとう","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"大正","pref":"石川県","address":"石川県金沢市大和町1-21","lat":36.56789142,"lng":136.63982834,"geo_status":"db","era":"大正8年／平成8年改修","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"木造2階建、瓦葺一部鉄板葺、建築面積381㎡","structure_material":"木造2階建","registered":"2012.08.13(平成24.08.13)","register_no":"17 － 0241","desc":"紡績工場の事務所棟として建設。木造二階建、建築面積三八一平方メートル、寄棟造桟瓦葺でＬ字形平面の東角を隅切して玄関を構える。北面を吹放しの廊下とし、南面に階段室と便所を配する。外壁は下見板張で欄間付上下窓を連ねる。簡潔な意匠の事務所建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00009264"},{"id":"00000041","register_sub_id":"101","register_pk":"101031","name":"金沢市立玉川図書館別館（旧専売公社C-1号工場）","kana":"かなざわしりつたまがわとしょかんべっかん（きゅうせんばいこうしゃしーいちごうこうじょう）","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県金沢市玉川町２-20","lat":36.57004075,"lng":136.65159661,"geo_status":"db","era":"明治44","year":1911,"year_source":"db","year_min":1911,"year_max":1911,"year_label":null,"structure":"煉瓦造2階建、瓦葺、建築面積691㎡","structure_material":"煉瓦造2階建","registered":"1996.12.20(平成8.12.20)","register_no":"17 － 0001","desc":"大蔵省臨時建築部によって建設された煙草工場で，設計は建築部長妻木頼黄の下で矢橋賢吉が手がけたと推定されている。１・２階を一体に扱う窓廻りのアーチの構成と煉瓦造の外観に特徴があり，明治の大蔵省臨時建築部の作風を示す標準となる好例である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000041"},{"id":"00011285","register_sub_id":"101","register_pk":"209121","name":"旧北森酒店店舗兼主屋","kana":"きゅうきたもりさけてんてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県小松市粟津町カ8-5","lat":36.332625,"lng":136.446941,"geo_status":"db","era":"明治33頃／平成25改修","year":1900,"year_source":"db","year_min":1900,"year_max":1900,"year_label":null,"structure":"木造2階建、瓦葺、建築面積231㎡","structure_material":"木造2階建","registered":"2016.11.29(平成28.11.29)","register_no":"17－0262","desc":"粟津温泉街の中心部に所在するもと造酒屋で、近隣の旅館に日本酒を卸していた。二階建で平面は前広間型を基本とし、屋根はやや起りのある切妻造妻入で桟瓦葺とし、妻面に小屋束と貫、梁を現し、左右に片流の下屋を付けるなど、当地域の民家の特徴をよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011285"},{"id":"00003227","register_sub_id":"101","register_pk":"104217","name":"旧山長織物会社石蔵","kana":"きゅうやまちょうおりものがいしゃいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺番場町18-2","lat":36.309517,"lng":136.3108339,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木骨石造2階建、瓦葺、建築面積64㎡","structure_material":"木骨石造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0067","desc":"事務所の東方，旧大聖寺川沿い道路際に南北棟で建つ。桁行４間梁間３間規模，越前瓦葺，切妻造の２階建で，西面全面に１間半幅の下屋を差掛けて蔵前をとる。生糸の保管蔵で，地元産の凝灰岩を用いた木骨石造とし，入口に金庫風の観音扉，窓には鉄扉を付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003227"},{"id":"00003226","register_sub_id":"101","register_pk":"104216","name":"旧山長織物会社事務所","kana":"きゅうやまちょうおりものがいしゃじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺番場町18-2","lat":36.309654,"lng":136.310608,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造2階建、瓦葺、建築面積129㎡","structure_material":"木造2階建","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0066","desc":"旧大聖寺川沿岸に位置し，南面して建つ。桁行８間梁間３間規模，越前瓦葺，寄棟造の木造総２階建の南面に寄棟の車寄を突出し，背面に１間幅の下屋を付ける。外壁をイギリス下見板張とした洋館風の事務所建築で，開口部を大きくとっている点に特徴がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003226"},{"id":"00003228","register_sub_id":"101","register_pk":"104218","name":"旧山長織物会社門","kana":"きゅうやまちょうおりものがいしゃもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"明治","pref":"石川県","address":"石川県加賀市大聖寺番場町18-2","lat":36.30953106,"lng":136.31057943,"geo_status":"db","era":"明治43","year":1910,"year_source":"db","year_min":1910,"year_max":1910,"year_label":null,"structure":"木造、瓦葺、間口6m","structure_material":"木造","registered":"2003.03.18(平成15.03.18)","register_no":"17 － 0068","desc":"事務所玄関車寄の東南方に位置し，道路からやや退いて建つ。切妻造，越前瓦葺の腕木門で，１間１戸として両開戸を付け，背後に控柱を建てる。左右両脇には半間幅の通用口を設け，越前瓦葺，切妻造の小屋根を架けて織物会社正面の景観を整えている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00003228"},{"id":"00012899","register_sub_id":"101","register_pk":"368002","name":"小松市立錦窯展示館石蔵","kana":"こまつしりつにしきがまてんじかんいしぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県小松市大文字町95-2他","lat":36.40325556,"lng":136.44836389,"geo_status":"db","era":"昭和40年頃／平成10年改修","year":1965,"year_source":"db","year_min":1965,"year_max":1965,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積9.6㎡","structure_material":"石造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 288","desc":"敷地東南隅に西面して建つ完成品の旧収蔵庫。切妻造桟瓦葺妻入の平屋建で、外壁を観音下石積とする。正面は出入口に鳥居枠を組んで鉄扉を備え、石材表面に縦溝や面取を施すなど丁寧につくる。内部は大壁造の一室で、和小屋を現す。屋敷奥の構えを引き締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012899"},{"id":"00012898","register_sub_id":"101","register_pk":"368001","name":"小松市立錦窯展示館窯納屋","kana":"こまつしりつにしきがまてんじかんかまなや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県小松市大文字町95-2他","lat":36.40325833,"lng":136.44803889,"geo_status":"db","era":"昭和8年頃／平成10年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積38㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 287","desc":"主屋の南側に建つ切妻造桟瓦葺の木造二階建で、西面を通りに面する。外壁は一階を簓子下見板張の腰石張、二階を漆喰塗とする。内部は石敷土間で、東を吹抜けとして大小二基の錦窯を備え、西は一階を薪置場、二階を倉庫とする。九谷焼窯納屋の希少な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012898"},{"id":"00012897","register_sub_id":"101","register_pk":"368000","name":"小松市立錦窯展示館主屋","kana":"こまつしりつにしきがまてんじかんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県小松市大文字町95-2他","lat":36.40332222,"lng":136.44808889,"geo_status":"db","era":"昭和8年頃／平成10年改修","year":1933,"year_source":"db","year_min":1933,"year_max":1933,"year_label":null,"structure":"木造2階建、瓦葺、建築面積92㎡","structure_material":"木造2階建","registered":"2019.09.10(令和1.09.10)","register_no":"17 － 286","desc":"小松旧市街にある陶工・徳田八十吉の旧居兼陶房。主屋は前庭を介して通りに西面して建つ木造二階建、切妻造桟瓦葺。1階南側を土間とし、北側にミセや座敷等四室を並べる。二階は7室を配し、上絵付の作業場とする。九谷焼窯元の暮らしを伝える近代和風住宅。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012897"},{"id":"00005130","register_sub_id":"101","register_pk":"106120","name":"橋本酒造釜場及び白米庫","kana":"はしもとしゅぞうかまばおよびはくまいこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32757914,"lng":136.38605911,"geo_status":"db","era":"昭和29","year":1954,"year_source":"db","year_min":1954,"year_max":1954,"year_label":null,"structure":"鉄骨石造平屋建、瓦葺、建築面積171㎡","structure_material":"鉄骨石造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0141","desc":"清酒蔵の南方に東西棟で建つ。桁行１１間，梁間５間，切妻造，桟瓦葺の平屋建で，仕込蔵として建設。構造は外周に鉄骨柱を建て，外側に凝灰岩を積んだ鉄骨石造で，小屋組は鉄骨のフィンクトラスとする。ＲＣ造へ移行する過渡期の構造の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005130"},{"id":"00005128","register_sub_id":"101","register_pk":"106118","name":"橋本酒造清酒蔵","kana":"はしもとしゅぞうせいしゅぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32770677,"lng":136.38604138,"geo_status":"db","era":"大正14","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積159㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0139","desc":"槽場の西方，貯蔵庫の南西方に位置し，東西棟で建つ。規模は桁行７間半，梁間６間で，切妻造，桟瓦葺，妻入の２階建酒蔵で，１階内部の２列の柱６本が２階床を支持し，２階中央２本の柱で地棟を支える整然とした構造で，外周の壁内側に凝灰岩を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005128"},{"id":"00005127","register_sub_id":"101","register_pk":"106117","name":"橋本酒造貯蔵庫","kana":"はしもとしゅぞうちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.32782094,"lng":136.38613475,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0138","desc":"槽場の北面西寄りに接続して南北棟で建つ。桁行９間，梁間４間半規模，切妻造，桟瓦葺，妻入の２階建酒蔵で，南西隅に階段を設け，内部棟通りの２本の柱と妻面の棟持柱が地棟を支持する。槽場と同様に，外周の壁内側に凝灰岩を張り，大棟には笏谷石を置く。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005127"},{"id":"00005126","register_sub_id":"101","register_pk":"106116","name":"橋本酒造槽場","kana":"はしもとしゅぞうふなば","category":"産業2次","subcategory":"建築物","type_guess":"橋","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県加賀市動橋町イ184","lat":36.3276718,"lng":136.38621413,"geo_status":"db","era":"文化5","year":1808,"year_source":"db","year_min":1808,"year_max":1808,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積145㎡","structure_material":"土蔵造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"17 － 0137","desc":"石蔵の南方，主屋通り庭の西側に接して東西棟で建つ。桁行１０間半，梁間４間規模，切妻造，桟瓦葺で，主屋側土扉金具に「文化五年辰七月吉日」と記す。外周は半間毎に柱を建て，外側に凝灰岩を張り，さらに外側に土壁層を設けて漆喰塗り仕上げとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005126"},{"id":"00007477","register_sub_id":"101","register_pk":"108459","name":"東酒造場大門","kana":"ひがししゅぞうじょうおおもん","category":"産業2次","subcategory":"建築物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432186,"lng":136.480576,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積69㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0203","desc":"敷地東辺の中央、通りから入った所に蔵に挟まれて建つ。両下造桟瓦葺の長屋門で、南半部は作業場と一体の空間をつくる。北側の門口４．７ｍに両開の大戸と潜りを設け、正面南寄りは石積基礎に漆喰壁で高く腰板を張り出格子窓を付け、屋敷構えに風格を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007477"},{"id":"00007478","register_sub_id":"101","register_pk":"108460","name":"東酒造場勝手口","kana":"ひがししゅぞうじょうかってぐち","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432346,"lng":136.480423,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造、瓦葺、間口1.7m、左右塀付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0204","desc":"敷地北辺の中央、主屋と道具蔵の間に建つ。間口１．７ｍと小規模な薬医門で、東西棟の切妻造桟瓦葺。洋風を加味したの道具蔵と対照的に軽やかな和風意匠とする。両脇に続く袖塀は、切石を高く積み上げ、その上に東側は土塀、西側は板塀を造り、総延長８．６ｍ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007478"},{"id":"00007474","register_sub_id":"101","register_pk":"108456","name":"東酒造場桂松庵","kana":"ひがししゅぞうじょうけいしょうあん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432198,"lng":136.480133,"geo_status":"db","era":"昭和27","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積18㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0200","desc":"麹室の北に接し、主屋西側の庭園に面する四畳半茶室。南北棟の入母屋造で、軒先を銅板とする桟瓦葺とし、北・東面に銅板葺庇を付ける。網代組や筵を組み合わせた天井をもち、障子窓や貴人口から光を採り込み、明るく軽快な茶室に仕上げている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007474"},{"id":"00007472","register_sub_id":"101","register_pk":"108454","name":"東酒造場検査室","kana":"ひがししゅぞうじょうけんさしつ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43211948,"lng":136.48015686,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積59㎡","structure_material":"木造2階一部平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0198","desc":"西蔵と中蔵の間に建つ。桁行３．６ｍ梁間３．２ｍの木造２階建で、切妻造桟瓦葺とし、北側に広い下屋を付ける。内部は白漆喰仕上げ大壁造で、天井まで塗り上げる。南面外壁は石積基礎上に下見板張とし、ベイウィンドウを設け、窓にはステンドグラスを入れる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007472"},{"id":"00007473","register_sub_id":"101","register_pk":"108455","name":"東酒造場麹室","kana":"ひがししゅぞうじょうこうじしつ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43215348,"lng":136.48010128,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積62㎡","structure_material":"石造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0199","desc":"敷地西辺、西蔵の北側に隣接する。桁行７．４ｍ梁間８．３ｍの規模の小さい石造平屋建で、切妻造桟瓦葺とする。観音下石を軒まで積み上げ、妻壁の上部は真壁に小屋架構を現す。石積の重厚な外壁上に掛かる、軽快な屋根が印象的である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007473"},{"id":"00007470","register_sub_id":"101","register_pk":"108452","name":"東酒造場作業場","kana":"ひがししゅぞうじょうさぎょうば","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43215659,"lng":136.48038269,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造平屋一部2階建、瓦葺及び鉄板葺、建築面積178㎡、煙突付","structure_material":"木造平屋一部2階建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0196","desc":"東蔵と中蔵の間にある切妻造２階建の酒母室と休憩室や、東蔵や中蔵の北面に一連で続く釜場などの作業空間からなる。北面は下見板張の真壁や出格子窓、煉瓦造の煙突、複雑に架かる屋根など変化に富む外観をつくり、通りの酒母室南面は石積で街路景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007470"},{"id":"00007467","register_sub_id":"101","register_pk":"108449","name":"東酒造場店舗兼主屋","kana":"ひがししゅぞうじょうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43224783,"lng":136.480255,"geo_status":"db","era":"昭和11／昭和57頃改修","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積232㎡","structure_material":"木造2階一部平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0193","desc":"敷地の中央北寄りに東面する。正面に入母屋造桟瓦葺の２階建、背面に直交する入母屋造平屋建を設ける。内部は前方南半に土間、北にオイ、後方に田の字型に４室を配し、彫刻欄間を飾る。伝統的な間取を受け継ぎながら、外観や平面ほかに近代性を反映する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007467"},{"id":"00007476","register_sub_id":"101","register_pk":"108458","name":"東酒造場道具蔵","kana":"ひがししゅぞうじょうどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43227317,"lng":136.48034938,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積84㎡","structure_material":"木造2階一部平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0202","desc":"敷地北辺、主屋の東方に建つ。桁行７．７ｍ梁間５．９ｍ規模の切妻造桟瓦葺で、南面に蔵前を設ける。木造２階建で、外壁に切石を積み上げ、開口部に半円アーチなどの洋風意匠を取り入れ、上下の窓の間には竜虎の彫刻を施す。丁寧な装飾が施された石蔵の好例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007476"},{"id":"00007469","register_sub_id":"101","register_pk":"108451","name":"東酒造場中蔵","kana":"ひがししゅぞうじょうなかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432098,"lng":136.48031672,"geo_status":"db","era":"昭和24","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積178㎡","structure_material":"木造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0195","desc":"敷地南辺、東蔵の西方に建つ。桁行１９ｍ梁間９．５ｍの切妻造桟瓦葺。木造２階建で、柱外側に観音下石を積み上げ、内部を白漆喰で仕上げる。東蔵と共通する外観であるが、鉢巻を簡略にし、出入口の外側楣上に半円アーチと楔石の装飾をするなど、違いを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007469"},{"id":"00007471","register_sub_id":"101","register_pk":"108453","name":"東酒造場西蔵","kana":"ひがししゅぞうじょうにしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.432083,"lng":136.480103,"geo_status":"db","era":"慶応4／明治35移築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0197","desc":"敷地の南辺西端に建つ土蔵造２階建。桁行９．５ｍ梁間５．９ｍの切妻造妻入桟瓦葺。東面に出入口、南・西面に窓を開け、窓枠等に石材を用いる。江戸切仕上げの石積基礎上に、高く下見板張とし、軒まわりにも石材をまわす。石蔵が連続する景観に変化を与える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007471"},{"id":"00007468","register_sub_id":"101","register_pk":"108450","name":"東酒造場東蔵","kana":"ひがししゅぞうじょうひがしぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.43211,"lng":136.48056,"geo_status":"db","era":"昭和21","year":1946,"year_source":"db","year_min":1946,"year_max":1946,"year_label":null,"structure":"石造平屋建、瓦葺、建築面積139㎡","structure_material":"石造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0194","desc":"敷地の南辺東端に建つ。桁行１５ｍ梁間９．４ｍの石造平屋建。切妻造妻入桟瓦葺とし、西面の酒母室側に入口を設け引分け戸をたてる。内部は一室で、漆喰仕上げ、トラス組とする。地元産の観音下石を積み上げ、腰部を江戸切仕上げとする。重厚で趣のある石蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007468"},{"id":"00007475","register_sub_id":"101","register_pk":"108457","name":"東酒造場緑寿庵","kana":"ひがししゅぞうじょうりょくじゅあん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"石川県","address":"石川県小松市野田町丁35","lat":36.4322891,"lng":136.48009652,"geo_status":"db","era":"昭和23","year":1948,"year_source":"db","year_min":1948,"year_max":1948,"year_label":null,"structure":"木造平屋建、瓦葺及び銅板葺、建築面積46㎡","structure_material":"木造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"17 － 0201","desc":"敷地の北西隅に位置する。南北棟の入母屋造桟瓦葺で、庭側の南から東面に深い土庇、東面北寄りに入母屋造の玄関を設ける。庭園に面する主座敷には、大きくトコとトコ脇を構え、花頭形に開ける付書院を備え、緩やかな折上格天井を張り、格式のある空間をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007475"},{"id":"00002919","register_sub_id":"101","register_pk":"103909","name":"やちや酒造酒蔵","kana":"やちやしゅぞうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市大樋町232","lat":36.585922,"lng":136.675613,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積132㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"17 － 0061","desc":"金沢城北方に所在する老舗の造り酒屋。南北に長い敷地中央に建つ道具蔵の北側にあり，主屋とほぼ同時期のものと思われ，伝統的な酒造産業に欠かせない施設。東西棟で桟瓦葺，桁行約約１９ｍで２階建の細長い建物で，酒蔵らしい空間構成をよく保持している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002919"},{"id":"00002917","register_sub_id":"101","register_pk":"103907","name":"やちや酒造主屋","kana":"やちやしゅぞうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"石川県","address":"石川県金沢市大樋町232","lat":36.585617,"lng":136.675751,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"木造2階建、瓦葺、建築面積162㎡","structure_material":"木造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"17 － 0059","desc":"金沢城北方に所在する老舗の造り酒屋。南北に長い敷地で，南側街路に面して建つ主屋は，間口７間の２階建で，屋根は切妻造・桟瓦葺，幅広の下屋庇をつける。改造はあるのもの，伝統的な外観を保ち，内部も豪快な梁組をみせるなど，商家のつくりをよく伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002917"},{"id":"00002918","register_sub_id":"101","register_pk":"103908","name":"やちや酒造道具蔵","kana":"やちやしゅぞうどうぐぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"石川県","address":"石川県金沢市大樋町232","lat":36.585812,"lng":136.675583,"geo_status":"db","era":"江戸後期","year":1801,"year_source":"estimated","year_min":1751,"year_max":1830,"year_label":"江戸後期","structure":"土蔵造2階建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建","registered":"2002.08.21(平成14.08.21)","register_no":"17 － 0060","desc":"金沢城北方に所在する老舗の造り酒屋。南側の主屋後方，南北に長い敷地中央に建ち，主屋とほぼ同時期のものと思われる。製造業の屋敷構成に欠かせない施設。木造・２階建の土蔵造で，戸口に黒漆喰塗の観音扉を用いるなど，重厚で丁寧なつくりである。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002918"},{"id":"00013246","register_sub_id":"101","register_pk":"366235","name":"青木蘭麝堂酒蔵","kana":"あおきらんじゃどうさかぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"福井県","address":"福井県福井市脇三ケ町25字谷口19","lat":36.01871111,"lng":136.29104444,"geo_status":"db","era":"寛政12年(1800)／明治後期増築、昭和37年頃改修","year":1800,"year_source":"db","year_min":1800,"year_max":1800,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積218㎡","structure_material":"土蔵造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"18 － 0201","desc":"敷地中央に位置し、主屋の東側に続く土蔵造東西棟の中蔵、その東側に隣接する土蔵造南北棟の酒蔵、それらの南側に架かる下屋からなる。外壁は白漆喰塗で、腰を簓子下見板張とし、内部には仕込室、薬酒製造室、保管室等を配す。薬酒製造の中心施設である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013246"},{"id":"00013244","register_sub_id":"101","register_pk":"366233","name":"青木蘭麝堂新座敷","kana":"あおきらんじゃどうしんざしき","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市脇三ケ町25字谷口19","lat":36.01881667,"lng":136.290925,"geo_status":"db","era":"明治前期／昭和前期・同44年改修","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、金属板葺、建築面積22㎡","structure_material":"木造平屋建","registered":"2020.04.03(令和2.04.03)","register_no":"18 － 0199","desc":"市東部の御茸山山裾に位置し、南面する敷地北寄りに建つ主屋北側に接続する。木造平屋建で東側の庭園鑑賞のために建てた。外壁は白漆喰塗を基本とし、一部下見板張とする。内部は床付の六畳間一室で、全体的に面皮材や丸太を多用し、数奇屋風意匠でまとめる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013244"},{"id":"00013245","register_sub_id":"101","register_pk":"366234","name":"青木蘭麝堂離れ","kana":"あおきらんじゃどうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県福井市脇三ケ町25字谷口19","lat":36.01877778,"lng":136.29078611,"geo_status":"db","era":"大正7年","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、金属板葺、建築面積15㎡","structure_material":"木造2階建","registered":"2020.04.03(令和2.04.03)","register_no":"18 － 0200","desc":"新座敷の西側に位置し、南東部が主屋の北側に接続する。木造二階建、入母屋造金属板葺で、外壁は黄漆喰塗、一部下見板張とする。二階に三畳の前室と四畳半の床付の座敷を設け、手摺越しに南西に広がる庭園を望む。敷地北西隅の中庭周囲の景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013245"},{"id":"00013719","register_sub_id":"101","register_pk":"505253","name":"岩野平三郎製紙所主屋","kana":"いわのへいざぶろうせいししょおもや","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市大滝町27字岩上4他","lat":35.90448333,"lng":136.24981667,"geo_status":"db","era":"明治元年／大正後期増築、昭和8年頃・同30年頃改修、同中期増築","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階一部平屋建、瓦葺、建築面積218㎡","structure_material":"木造2階一部平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 221","desc":"事務所北西に接続し、東面して建つ。二階建切妻造桟瓦葺の北棟と棟を直行させた南棟を平屋で接続し東・北面に深い下屋を付す。外壁は真壁造で腰は下見板一部竪板張。北棟を居室部、平屋を内玄関とし、南棟は台所や和室とする。風格ある屋敷構えを構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013719"},{"id":"00013726","register_sub_id":"101","register_pk":"504975","name":"岩野平三郎製紙所旧大工小屋","kana":"いわのへいざぶろうせいししょきゅうだいくごや","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.9044,"lng":136.25000556,"geo_status":"db","era":"昭和31年","year":1956,"year_source":"db","year_min":1956,"year_max":1956,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積34㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 228","desc":"コグラの北に近接し西面して建つ。もと和紙出荷用の梱包木箱の製作所と伝える。木造平屋建、切妻造桟瓦葺で、西面に下屋を架ける。外壁は下見板張で上部を土壁とする。内部は一室で土間床に竪板張の壁とし、束立の和小屋を現す。敷地中ほどの一点景をつくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013726"},{"id":"00013725","register_sub_id":"101","register_pk":"504974","name":"岩野平三郎製紙所コグラ","kana":"いわのへいざぶろうせいししょこぐら","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90433611,"lng":136.25,"geo_status":"db","era":"昭和24年","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"木造2階建、瓦葺、建築面積41㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 227","desc":"事務所の東方、街路に沿って南面して建つ。もと大判和紙の乾燥場。土蔵造二階建、桟瓦葺で背面に下屋を付す。外壁は漆喰で軒先まで塗込め腰をモルタル塗とする。内部は上下階とも一室で一階は土壁、二階は竪板張。煮釜場と共に敷地東辺の沿道景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013725"},{"id":"00013718","register_sub_id":"101","register_pk":"504971","name":"岩野平三郎製紙所事務所","kana":"いわのへいざぶろうせいししょじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"事務所","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市大滝町27字岩上4他","lat":35.90436111,"lng":136.24988333,"geo_status":"db","era":"明治元年／昭和中期","year":1868,"year_source":"db","year_min":1868,"year_max":1868,"year_label":null,"structure":"木造2階建、瓦葺、建築面積68㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 220","desc":"越前和紙の産地、旧今立町にある製紙所。事務所は谷間の南北に長い敷地中央北寄に南面して建つ。木造二階建、切妻造桟瓦葺で正面に下屋を付す。外壁は下見板一部竪板張で、上部は真壁造。内部一階は事務室、二階は和室を配する。敷地北半の屋敷景観を整える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013718"},{"id":"00013723","register_sub_id":"101","register_pk":"504973","name":"岩野平三郎製紙所漉き場及び圧搾場","kana":"いわのへいざぶろうせいししょすきばおよびあっさくば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90390556,"lng":136.24998889,"geo_status":"db","era":"大正後期／昭和28年改修","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"木造平屋一部2階建、瓦葺、建築面積407㎡","structure_material":"木造平屋一部2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 225","desc":"ビーター場の北に接続して建つ紙漉き、脱水用施設。切妻造のＬ字型平面で、東西棟の漉き場と南北棟で東面に下屋を付した圧搾場からなる。漉き場内部は天井が高く、南東面は上下二段に窓を開いて採光を図る。狭隘な敷地なりに建つ広大な施設が存在感を放つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013723"},{"id":"00013720","register_sub_id":"101","register_pk":"505255","name":"岩野平三郎製紙所土蔵及び繋ぎ屋","kana":"いわのへいざぶろうせいししょどぞうおよびつなぎや","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県越前市大滝町27字岩上4他","lat":35.90463889,"lng":136.24993056,"geo_status":"db","era":"大正後期","year":1922,"year_source":"estimated","year_min":1919,"year_max":1926,"year_label":"大正後期","structure":"土蔵造2階及び木造平屋建、瓦葺、建築面積125㎡","structure_material":"土蔵造2階及び木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 222","desc":"敷地北端に南面して建つ二階建の土蔵。正面に下屋を付し、外壁は漆喰で軒先まで塗込めて腰を下見板張とする。二階東側には床付の座敷を配する。土蔵南西に伸びて主屋に接続する繋ぎ屋は内部に風呂等を備える。丁寧なつくりで、北辺の屋敷景観を引締める。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013720"},{"id":"00013721","register_sub_id":"101","register_pk":"505257","name":"岩野平三郎製紙所煮釜場","kana":"いわのへいざぶろうせいししょにがまば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90417222,"lng":136.25001667,"geo_status":"db","era":"昭和27年","year":1952,"year_source":"db","year_min":1952,"year_max":1952,"year_label":null,"structure":"木造平屋建、鉄板葺、建築面積40㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 223","desc":"敷地中程東辺に西面して建つ原材料の繊維の煮沸、洗浄用の施設。片流れ鉄板葺の南北に長い平面で、敷地の高低なりに北半を一段低くつくる。外壁は竪板張とする。北半の二室と南半一室に区分し、南半に釜場と洗い場を設ける。和紙製造施設の沿道景観を構成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013721"},{"id":"00013724","register_sub_id":"101","register_pk":"505259","name":"岩野平三郎製紙所張り場及び乾燥場","kana":"いわのへいざぶろうせいししょはりばおよびかんそうば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90417222,"lng":136.24989167,"geo_status":"db","era":"昭和28年／同40年頃増築","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造2階建、瓦葺、建築面積236㎡","structure_material":"木造2階建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 226","desc":"圧搾場の北に接続し、東面して建つ。南北棟の木造二階建、切妻造桟瓦葺で、正面北寄出入口に庇を架ける。外壁は下見板一部竪板張とする。東側にトラスで大スパンをとばした大部屋の作業空間をつくり、西側に小部屋の乾燥室を配す。敷地中央の景観を形成。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013724"},{"id":"00013722","register_sub_id":"101","register_pk":"504972","name":"岩野平三郎製紙所ビーター場","kana":"いわのへいざぶろうせいししょびーたーば","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県越前市大滝町30字朝日16他","lat":35.90374444,"lng":136.25013889,"geo_status":"db","era":"昭和28年","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積145㎡","structure_material":"木造平屋建","registered":"2021.02.26(令和3.02.26)","register_no":"18 － 224","desc":"敷地南端に建つ原材料の繊維の塵取り、叩き解し用の施設。木造平屋建切妻造桟瓦葺で、南に下屋、北東に落棟の突出部を付す。外壁は下見板張で、連続した横長窓で開口を広くとる。内部はキングポストトラスの小屋組を現す大空間。一連の施設景観の南端を担う。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013722"},{"id":"00007208","register_sub_id":"101","register_pk":"108190","name":"越前和紙の里卯立の工芸館（旧西野家住宅主屋及び紙漉場）","kana":"えちぜんわしのさとうだつのこうげいかん（きゅうにしのけじゅうたくしゅおくおよびかみすきば）","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県越前市新在家町9字畔之内18他","lat":35.911171,"lng":136.244812,"geo_status":"db","era":"寛延元／平成9移築","year":1748,"year_source":"db","year_min":1748,"year_max":1748,"year_label":null,"structure":"木造平屋建、瓦葺、建築面積244㎡","structure_material":"木造平屋建","registered":"2008.07.08(平成20.07.08)","register_no":"18 － 0063","desc":"木造つし２階建、南北棟の妻入主屋の東に、木造つし２階建の南北棟の紙漉場が並ぶ。屋根は桟瓦葺で、主体部の両妻にウダツを立ち上げて特徴的な外観を呈する。内部は前半を土間と板間、後半を整形四間取の居室とする。２階への階段は移築時の後補である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007208"},{"id":"00007484","register_sub_id":"101","register_pk":"108466","name":"加藤吉平商店表門","kana":"かとうきちべいしょうてんおもてもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市吉江町1字一ノ割14","lat":35.98627814,"lng":136.17014769,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"木造、瓦葺、間口2.6m、左右袖塀付","structure_material":"木造","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0076","desc":"七曲りに東面して建つ。一間棟門で両側に板塀が続く。布基礎上に土台を置き、方柱を建て、腕木を出し、一軒疎垂木を支持。屋根は石置棟の切妻造桟瓦葺で、緩やかな起りをもつ。板塀は延長１５ｍ、竪板張で、屋根に桟瓦を葺く。伝統的な街路景観を構成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007484"},{"id":"00007483","register_sub_id":"101","register_pk":"108465","name":"加藤吉平商店土蔵","kana":"かとうきちべいしょうてんどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"江戸","pref":"福井県","address":"福井県鯖江市吉江町1字一ノ割14","lat":35.98640807,"lng":136.16991559,"geo_status":"db","era":"江戸末期","year":1849,"year_source":"estimated","year_min":1830,"year_max":1868,"year_label":"江戸末期","structure":"土蔵造2階建、瓦葺、建築面積61㎡","structure_material":"土蔵造2階建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0075","desc":"七曲りの西に占める屋敷地のほぼ中央に位置する。切石積基礎上に建つ土蔵造２階建。桁行９．５ｍ梁間５．７ｍ規模で、１、２階とも広い１室とする。切妻造妻入桟瓦葺とし、正面に庇を付け、その下に出入口を設け、両脇に分銅形の文様を施す腰板を張る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007483"},{"id":"00001697","register_sub_id":"101","register_pk":"102687","name":"旧鯖江地方織物検査所","kana":"きゅうさばえちほうおりものけんさじょ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県鯖江市旭町1-6-6","lat":35.9446189,"lng":136.1862299,"geo_status":"db","era":"昭和10","year":1935,"year_source":"db","year_min":1935,"year_max":1935,"year_label":null,"structure":"木造2階建、瓦葺、建築面積312㎡","structure_material":"木造2階建","registered":"2000.04.28(平成12.04.28)","register_no":"18 － 0013","desc":"人絹織物の検反所として建設。総二階建で、一階腰をドイツ下見縦板張とするほかは南京下見板張とし、軒下に白漆喰塗小壁を廻す。典型的な下見板張洋風建築。福井県下近代産業の中心を担った繊維関係事務所の数少ない遺構。さばえ現代美術センターとして活用。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00001697"},{"id":"00007479","register_sub_id":"101","register_pk":"108461","name":"旧紐育スタンダード石油会社倉庫北棟","kana":"きゅうにゅーよーくすたんだーどせきゆがいしゃそうこきたとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県敦賀市金ヶ崎町16-1","lat":35.66200521,"lng":136.07460786,"geo_status":"db","era":"明治38／昭和56・昭和58改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積513㎡","structure_material":"煉瓦造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0071","desc":"敦賀港の東部、金ヶ崎突堤の付け根に位置する敷地の北寄りに、西妻面を海側に向けて建つ。桁行３５ｍ梁間１５ｍ規模の煉瓦造平屋建、切妻造桟瓦葺とする。外壁に柱型を現して内壁を平滑にし、貯蔵の便に供した。近代敦賀港の面影を残す数少ない産業遺産である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007479"},{"id":"00007480","register_sub_id":"101","register_pk":"108462","name":"旧紐育スタンダード石油会社倉庫南棟","kana":"きゅうにゅーよーくすたんだーどせきゆがいしゃそうこみなみとう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県敦賀市金ヶ崎町16-1","lat":35.66186183,"lng":136.074539,"geo_status":"db","era":"明治38／昭和56・昭和58改修","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造平屋建、瓦葺、建築面積513㎡","structure_material":"煉瓦造平屋建","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0072","desc":"北棟と３ｍ隔てて平行して建ち、規模や形態を同じくする。煉瓦はイギリス積で、妻面上部の窓や平側中央の出入口まわりの装飾、鉄扉は当初のものである。内部に柱がなく、クィーンポストトラスが広い内部空間を実現する。北棟とともに県下最大規模の煉瓦造建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007480"},{"id":"00007481","register_sub_id":"101","register_pk":"108463","name":"旧紐育スタンダード石油会社倉庫煉瓦塀","kana":"きゅうにゅーよーくすたんだーどせきゆがいしゃそうこれんがべい","category":"産業2次","subcategory":"その他工作物","type_guess":"倉庫","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県敦賀市金ヶ崎町16-1","lat":35.66174183,"lng":136.07470862,"geo_status":"db","era":"明治38頃","year":1905,"year_source":"db","year_min":1905,"year_max":1905,"year_label":null,"structure":"煉瓦造、総延長92m","structure_material":"煉瓦造","registered":"2009.01.08(平成21.01.08)","register_no":"18 － 0073","desc":"道路で囲まれる敷地の北・東・南辺に設けられた煉瓦塀。イギリス積とし、高さ２．５ｍで、上部３段は迫り出し、天端をモルタルで仕上げる。総延長９２ｍに及び、１０～１５ｍ間隔に控えを付け、各面中央に開口を設ける。倉庫と一体で往時の港湾景観を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00007481"},{"id":"00008679","register_sub_id":"101","register_pk":"149400","name":"黒龍酒造店舗兼主屋","kana":"こくりゅうしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町松岡春日1-38他","lat":36.09121338,"lng":136.29901113,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積195㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0100","desc":"本町通りに南面して建つ。間口15ｍ奥行12ｍの木造つし2階建、切妻造桟瓦葺とし、正・背面に下屋を付ける。出入口を挟んで、左右に平格子と出格子、上屋には太い格子を中央6間に構え、両端間を黒漆喰で仕上げ、袖ウダツを付ける。風格ある大型町家である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008679"},{"id":"00008680","register_sub_id":"101","register_pk":"149401","name":"黒龍酒造離れ","kana":"こくりゅうしゅぞうはなれ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町松岡春日1-38他","lat":36.09131693,"lng":136.29912264,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造平屋建、瓦葺、建築面積54㎡","structure_material":"木造平屋建","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0101","desc":"店舗兼主屋の東面寄りに接する。東西棟の入母屋造桟瓦葺。木造平屋建で、建築面積54㎡。8畳の1室で、東面にトコと違棚を構える。南北に縁を設け、南庭側には室境に欄間を飾る。トコに銘木を用い、天井は黒漆塗の棹縁天井とするなど、良質な離れ座敷である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008680"},{"id":"00008681","register_sub_id":"101","register_pk":"149402","name":"黒龍酒造東門","kana":"こくりゅうしゅぞうひがしもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県吉田郡永平寺町松岡春日1-38他","lat":36.09121032,"lng":136.29915818,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、間口2.7m","structure_material":"木造","registered":"2011.07.25(平成23.07.25)","register_no":"18 － 0102","desc":"離れ南庭を挟み、通りに面して建つ。間口2.7ｍの腕木門。中央1.6ｍを門口として、両開板戸を吊り、両脇に腰板張の黒漆喰とする袖壁を造る。切妻造桟瓦葺。軒桁と冠木間に軒天井を張り、疎垂木を配る。基礎の笏谷石、黒壁、木部の弁柄の対比が印象的。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008681"},{"id":"00013382","register_sub_id":"101","register_pk":"368468","name":"信洋舎製紙所旧休憩場及び張場棟","kana":"しんようしゃせいしじょきゅうきゅうけいばおよびはりばとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市定友町五字相生12他","lat":35.91436389,"lng":136.24763611,"geo_status":"db","era":"明治19年","year":1886,"year_source":"db","year_min":1886,"year_max":1886,"year_label":null,"structure":"木造2階建、瓦葺、建築面積51㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0212","desc":"漉場棟の南、ボイラー及び旧ロール場棟の東に接続して東西棟で建つ。二階を張場とし、一階はかつて休憩場として使った。張場は、張り板に張った紙を乾燥させるための場所で、乾燥機を用いた専用の乾燥部屋も持つ。二階は採光通風のためガラス窓を大きく取る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013382"},{"id":"00013384","register_sub_id":"101","register_pk":"368470","name":"信洋舎製紙所旧塵取場及び仕上場棟","kana":"しんようしゃせいしじょきゅうちりとりばおよびしあげばとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市定友町五字相生12他","lat":35.91456111,"lng":136.24759444,"geo_status":"db","era":"明治32年","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"木造2階建、瓦葺、建築面積101㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0214","desc":"ボイラー及び旧ロール場棟の北に接続して建つ。桁行約一八メートル、梁間約５・５メートルで、二階を仕上場、一階を塵取場に使った。内部は広い一室空間とし、上下階ともガラス窓を連続させて採光通風に工夫する。地場産業である製紙の最終工程を担う建物。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013384"},{"id":"00013381","register_sub_id":"101","register_pk":"368467","name":"信洋舎製紙所漉場棟","kana":"しんようしゃせいしじょすきばとう","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県越前市定友町五字相生12他","lat":35.91444722,"lng":136.24771667,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積133㎡","structure_material":"木造平屋建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0211","desc":"大徳山麓の越前和紙の工房が並ぶ中に敷地を構える。桁行約一九メートル、梁間約6・5メートル、南北棟の工場建築で、内部を広い一室とする。紙を漉くための漉場として用いられる。採光通風のため、連続したガラス窓が内外の意匠を特徴付ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013381"},{"id":"00013383","register_sub_id":"101","register_pk":"368469","name":"信洋舎製紙所ボイラー及び旧ロール場棟","kana":"しんようしゃせいしじょぼいらーおよびきゅうろーるばとう","category":"産業2次","subcategory":"建築物","type_guess":"発電・機械","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県越前市定友町五字相生12他","lat":35.91441944,"lng":136.24755,"geo_status":"db","era":"明治中期","year":1890,"year_source":"estimated","year_min":1883,"year_max":1897,"year_label":"明治中期","structure":"木造2階建、瓦葺、建築面積122㎡","structure_material":"木造2階建","registered":"2020.08.17(令和2.08.17)","register_no":"18 － 0213","desc":"旧休憩場及び張場棟の西、旧塵取場及び仕上場棟の南に接続して南北棟で建つ。一階をボイラー室とし、二階を艶付けのためのロール場として使った。簡素な建物であるが、内部には明治期の艶付ロール機器も残され、製紙業の手工業からの近代化の過程を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013383"},{"id":"00008856","register_sub_id":"101","register_pk":"162299","name":"鳥浜酒造煙突","kana":"とりはましゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県三方上中郡若狭町鳥浜59天田30","lat":35.55310419,"lng":135.904289,"geo_status":"db","era":"昭和前期／昭和49年改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、高さ13m","structure_material":"煉瓦造","registered":"2011.10.28(平成23.10.28)","register_no":"18 － 0110","desc":"店舗兼醸造所の中央南側道路際に位置し、地中の煙道を通じて蔵前の蒸釜につながる煉瓦造の煙突である。基礎部分は方１．２ｍの正方形平面で、高さ１３ｍを測り、躯体はイギリス積で積み上げる。地域のシンボルとして親しまれる煉瓦煙突。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008856"},{"id":"00008855","register_sub_id":"101","register_pk":"162298","name":"鳥浜酒造店舗兼醸造所","kana":"とりはましゅぞうてんぽけんじょうぞうしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県三方上中郡若狭町鳥浜59天田30","lat":35.55322033,"lng":135.90416241,"geo_status":"db","era":"大正9年","year":1920,"year_source":"db","year_min":1920,"year_max":1920,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積395㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2011.10.28(平成23.10.28)","register_no":"18 － 0109","desc":"敷地中央に南面して建つ。建築面積３９５㎡で、主体部を土蔵造二階建、寄棟造桟瓦葺の醸造所とし、南側に店舗兼作業所、西側に事務所を下屋として附属する。錣葺形式の大屋根が、通り沿いに建つ煙突とともに造り酒屋の風情ある景観を構成している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008855"},{"id":"00002538","register_sub_id":"101","register_pk":"103528","name":"南部酒造場旧酒蔵大蔵","kana":"なんぶしゅぞうじょうきゅうさかぐらおおぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.984638,"lng":136.489777,"geo_status":"db","era":"大正8","year":1919,"year_source":"db","year_min":1919,"year_max":1919,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積152㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0019","desc":"前蔵の南方に建つ。前蔵とは棟方向を直交させた東西棟，切妻造，桟瓦葺，２階建の醸造蔵で，前蔵側と西面に入口を設ける。東妻面は１階部分を簓子下見，その上部を白漆喰塗とし，軒下の木製方杖や窓両脇の袖板などにより変化ある外観を四番通り側につくる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002538"},{"id":"00002537","register_sub_id":"101","register_pk":"103527","name":"南部酒造場旧酒蔵前蔵","kana":"なんぶしゅぞうじょうきゅうさかぐらまえぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.98474734,"lng":136.489822,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"土蔵造2階建、瓦葺、建築面積146㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0018","desc":"南部家は明治から「茶木屋」の屋号で造り酒屋を営む。前蔵は店舗の南方に建つ。南北棟，切妻造，桟瓦葺，妻入の２階建酒蔵で，桁行９間，梁間４間規模を有す。当地方にみられる簓子下見の外壁，軒下に方杖を廻した土蔵で，方杖を鉄製とする点に特色がある。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002537"},{"id":"00002540","register_sub_id":"101","register_pk":"103530","name":"南部酒造場米蔵","kana":"なんぶしゅぞうじょうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.9848373,"lng":136.4895927,"geo_status":"db","era":"明治22","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積41㎡","structure_material":"土蔵造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0021","desc":"西蔵の北方に建つ。西蔵とは棟方向を直交させた東西棟，切妻造，鉄板葺，妻入の２階建土蔵で，規模は桁行５間，梁間２間と西蔵よりも一回り小さい。外観は軒下に方杖をつけた当地方に広くみられる形式を持ち，敷地西辺に沿った背割下水側にも入口を開ける。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002540"},{"id":"00002536","register_sub_id":"101","register_pk":"103526","name":"南部酒造場店舗","kana":"なんぶしゅぞうじょうてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県大野市元町6-9～10","lat":35.98502,"lng":136.489853,"geo_status":"db","era":"明治期","year":1890,"year_source":"estimated","year_min":1868,"year_max":1912,"year_label":"明治期","structure":"木造2階建、瓦葺、建築面積398㎡","structure_material":"木造2階建","registered":"2001.11.20(平成13.11.20)","register_no":"18 － 0017","desc":"大野城下の中心地である七間通りと四番通りとが交差する南西角に北面して建つ。桁行５間半，梁間７間規模，切妻造，平入で，明治後期に西隣建物を購入しその東半を内部一体化する。当地方特有の袖壁を有した町家で，塔屋風越屋根がランドマークとなっている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00002536"},{"id":"00000727","register_sub_id":"101","register_pk":"101717","name":"平成大野屋本店二階蔵","kana":"へいせいおおのやほんてんにかいぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県大野市元町1-1","lat":35.98530711,"lng":136.48720864,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造２階建，瓦葺，建築面積164㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"18 － 0008","desc":"敷地の北奥に位置する２階建の土蔵で，外壁を簓子下見貼とする。もと大七銀行所有の土蔵で，内部は欅材を用いた質実な造りとし，隣接する戦後の福井大地震後のブレース入り土蔵と対照をなす。織物検査場設備の一翼を担う建物として重要である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000727"},{"id":"00012524","register_sub_id":"101","register_pk":"367819","name":"平成大野屋本店平蔵","kana":"へいせいおおのやほんてんひらぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"福井県","address":"福井県大野市元町1-1","lat":35.985008,"lng":136.48703,"geo_status":"geocoded","era":"昭和28年／平成12年改修","year":1953,"year_source":"db","year_min":1953,"year_max":1953,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積133㎡","structure_material":"土蔵造平屋建","registered":"2018.11.02(平成30.11.02)","register_no":"18 － 0194","desc":"敷地西北隅に南北棟で建つ。土蔵造平屋建、切妻造妻入で、南北二面に戸口を開く。鉄筋コンクリート造基礎に土台を据え、半間毎に立てた柱を胴差と筋交で固め、キングポストトラスの小屋組は方杖や火打梁で補強する。福井地震後の堅牢な構造技法の好例を示す。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012524"},{"id":"00000726","register_sub_id":"101","register_pk":"101716","name":"平成大野屋本店洋館","kana":"へいせいおおのやほんてんようかん","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"昭和前","pref":"福井県","address":"福井県大野市元町1-1","lat":35.98506643,"lng":136.48722095,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造２階建，瓦葺，建築面積426㎡","structure_material":"木造２階建","registered":"1998.09.02(平成10.09.02)","register_no":"18 － 0007","desc":"大野織物工業協同組合の織物検査場として建設。絹織物の生産地として栄えた大野の町を象徴する建造物として親しまれている。織物検査室を真北に向け，北面に大きな連続窓を設けている点に特徴がある。設計は福井市の今藤仁三郎，施工は地元の山形甚吉。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000726"},{"id":"00015436","register_sub_id":"101","register_pk":"533451","name":"マタイチ醤油醸造場店舗兼主屋","kana":"またいちしょうゆじょうぞうじょうてんぽけんおもや","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県越前市南二丁目22","lat":35.89212778,"lng":136.16609167,"geo_status":"db","era":"昭和11年","year":1936,"year_source":"db","year_min":1936,"year_max":1936,"year_label":null,"structure":"木造2階建、瓦葺、建築面積188㎡","structure_material":"木造2階建","registered":"2025.08.06(令和7.08.06)","register_no":"18 - 0261","desc":"北陸道に東面する醤油醸造業の店舗兼主屋。２階建切妻造平入桟瓦葺で一階は平格子を建て、二階外壁はモルタル塗仕上で軒を塗込め蛇腹を付す。一階は土間沿いに部屋を一列に並べ、二階西端は一五畳の座敷。土間内に井戸などを残し、醸造業の様相を伝える町家。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00015436"},{"id":"00010448","register_sub_id":"101","register_pk":"199407","name":"安本酒造煙突","kana":"やすもとしゅぞうえんとつ","category":"産業2次","subcategory":"その他工作物","type_guess":"煙突","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015656,"lng":136.27683,"geo_status":"db","era":"昭和前期／昭和中期改修","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"煉瓦造、高さ4.7m、面積1.1㎡","structure_material":"煉瓦造","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0131","desc":"仕込蔵一の北方に建つ煉瓦造煙突。焚口は仕込蔵内の蒸し場にあった。基部の外法が一辺約一メートルの正方形平面を持ち、イギリス積とする。昭和二三年の福井地震で被災し、現在は高さ約四・七メートルが残されている。酒造場の仕込み場の様子を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010448"},{"id":"00010449","register_sub_id":"101","register_pk":"199408","name":"安本酒造表門","kana":"やすもとしゅぞうおもてもん","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.01567487,"lng":136.27686891,"geo_status":"db","era":"昭和初期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和初期","structure":"木造、瓦葺、間口3.8m、左右袖塀付","structure_material":"木造","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0132","desc":"店舗兼主屋の東側に、街道に面して建つ。腕木門で左右に袖塀を廻らす。間口が約三・八メートルと広く、繰形のついた女梁で男梁を差出し、軒の出は約九〇センチメートルと深めである。吹寄垂木の軒先に菱形の地紋彫を施した淀を取り付ける手の込んだ意匠の門。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010449"},{"id":"00010442","register_sub_id":"101","register_pk":"199401","name":"安本酒造米蔵","kana":"やすもとしゅぞうこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015595,"lng":136.276602,"geo_status":"db","era":"明治21／明治後期改修","year":1888,"year_source":"db","year_min":1888,"year_max":1888,"year_label":null,"structure":"土蔵造2階建及び木造平屋建、瓦葺、建築面積45㎡","structure_material":"土蔵造2階建及び木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0125","desc":"街道へ面する敷地の西北隅、主屋の西隣に並び建つ。二階建土蔵と、平屋建の倉庫からなる。土蔵は南北棟で上部を漆喰で仕上げて小窓をあけ、小屋を登梁とする。倉庫は東側に接続して建ち、切妻造桟瓦葺とし、越屋根を設ける。街道の歴史的な景観に寄与している。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010442"},{"id":"00010444","register_sub_id":"101","register_pk":"199403","name":"安本酒造仕込蔵一","kana":"やすもとしゅぞうしこみぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015595,"lng":136.276859,"geo_status":"db","era":"明治22／昭和12改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造及び土蔵造平屋建並びに土蔵造2階建、瓦葺、建築面積205㎡","structure_material":"木造及び土蔵造平屋建並びに土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0127","desc":"主屋の東方、表門から煙突を挟んで南北に建つ長大な土蔵。北から旧精米所、旧酒米蒸し場と仕込場を配する。南側の仕込場は二階建土蔵で、一階に貯蔵タンクを並べ、二階に麹室を置く。外壁は漆喰塗で、腰を下見板張とする。酒造場の景観を形成する土蔵。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010444"},{"id":"00010445","register_sub_id":"101","register_pk":"199404","name":"安本酒造仕込蔵二","kana":"やすもとしゅぞうしこみぐらに","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015317,"lng":136.277023,"geo_status":"db","era":"明治41","year":1908,"year_source":"db","year_min":1908,"year_max":1908,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積102㎡","structure_material":"土蔵造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0128","desc":"上槽場の東に作業場を介して建つ。南北棟の二階建土蔵で、漆喰塗とし、軒下まで簓子下見板張とする。小屋組は登梁としており、内部は一本の独立柱のみで支える発達した構造を見せ、一階には仕込みに用いるタンクを並べる。造酒屋の歴史的な景観を見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010445"},{"id":"00010446","register_sub_id":"101","register_pk":"199405","name":"安本酒造上槽場","kana":"やすもとしゅぞうじょうそうば","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015342,"lng":136.276866,"geo_status":"db","era":"大正7／昭和2改修","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造及び土蔵造平屋一部2階建、金属板葺及び瓦葺、建築面積197㎡","structure_material":"木造及び土蔵造平屋一部2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0129","desc":"仕込蔵一の南方に接続して建つ。上槽場は、上槽場及び作業場、冷蔵倉庫、旧酛場からなる。上槽場及び作業場は、木造平屋建で搾りなどを行う場所である。外観に現れる旧酛場は平屋建土蔵と下屋からなり、中塗仕上げの外壁が素朴な味わいを見せる。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010446"},{"id":"00010441","register_sub_id":"101","register_pk":"199400","name":"安本酒造店舗兼主屋","kana":"やすもとしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.01559,"lng":136.276755,"geo_status":"db","era":"明治22／明治後期改修","year":1889,"year_source":"db","year_min":1889,"year_max":1889,"year_label":null,"structure":"木造2階建、金属板葺、建築面積156㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0124","desc":"一乗谷へ向かう旧街道沿いに北面する酒造所。店舗兼主屋は二階建の町家で、前後に下屋を付す。中央を玄関と店舗とし、西方に応接間、背面側に十畳座敷二室を配する。座敷は床と付書院を持ち、欄間などには繊細な組子細工を施しており、上質な飾りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010441"},{"id":"00010443","register_sub_id":"101","register_pk":"199402","name":"安本酒造土蔵","kana":"やすもとしゅぞうどぞう","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"high","period":"大正","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015349,"lng":136.276681,"geo_status":"db","era":"大正7","year":1918,"year_source":"db","year_min":1918,"year_max":1918,"year_label":null,"structure":"木造2階建、瓦葺、建築面積49㎡","structure_material":"木造2階建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0126","desc":"敷地西辺中央に位置する。南北棟の二階建土蔵、切妻造桟瓦葺で、妻壁の拝み部分に扇形の蔵印を施す。小屋組は登梁を地棟に架けている。二階に六箇所の窓が設けられ、漆喰塗の窓枠を外壁に張り出して、外観上のアクセントとしている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010443"},{"id":"00010447","register_sub_id":"101","register_pk":"199406","name":"安本酒造瓶詰め工場","kana":"やすもとしゅぞうびんづめこうじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.015245,"lng":136.276859,"geo_status":"db","era":"昭和12","year":1937,"year_source":"db","year_min":1937,"year_max":1937,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積65㎡","structure_material":"木造平屋建","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0130","desc":"敷地の南端に東西棟で建つ、平屋建の長い切妻造の建物である。南側外壁は真壁として腰に簓子下見板を張り、水平に連続する窓を設ける。内部は無柱の一室で、キングポストトラスの小屋組を架ける。南塀と一連の意匠になり、敷地背面の歴史的景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010447"},{"id":"00010450","register_sub_id":"101","register_pk":"199409","name":"安本酒造南塀","kana":"やすもとしゅぞうみなみべい","category":"産業2次","subcategory":"その他工作物","type_guess":"塀・門","type_guess_confidence":"high","period":"昭和前","pref":"福井県","address":"福井県福井市安原町7字下堀田4他","lat":36.01519155,"lng":136.27671858,"geo_status":"db","era":"昭和前期","year":1931,"year_source":"estimated","year_min":1926,"year_max":1945,"year_label":"昭和前期","structure":"木造、瓦葺、延長12m","structure_material":"木造","registered":"2015.03.26(平成27.03.26)","register_no":"18 － 0133","desc":"敷地南辺、瓶詰め工場の西側に続く土塀。延長約一二メートルを測り、笏谷石の基礎の上に土台を廻して建つ。下部に簓子下見板を張り、中間部を土壁として、上部を開放する。東寄りに片引きの板戸、西寄りに竪格子の窓二所を開く。洗練された意匠で境界を画す塀。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00010450"},{"id":"00004752","register_sub_id":"101","register_pk":"105742","name":"風間酒造酒造蔵","kana":"かざましゅぞうしゅぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市塩山下於曽910","lat":35.69755666,"lng":138.72696383,"geo_status":"db","era":"明治初期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治初期","structure":"土蔵造2階建、瓦葺、建築面積250㎡","structure_material":"土蔵造2階建","registered":"2005.07.12(平成17.07.12)","register_no":"19 － 0052","desc":"主屋背後に北面を道に接して建つ。桁行１２間，梁間６間，土蔵造２階建，桟瓦葺の置き屋根で，南面に下屋（オダレ）を掛ける。内部は独立柱を立て壁際を除き２階床を張り，中央桁行きに太い通し柱を並べ棟木を受ける。大規模で内外とも良質な酒造蔵の好事例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00004752"},{"id":"00013093","register_sub_id":"101","register_pk":"368366","name":"勝沼醸造主屋兼事務所","kana":"かつぬまじょうぞうしゅおくけんじむしょ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎371","lat":35.65613889,"lng":138.71581111,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積133㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0142","desc":"旧甲州街道の南の県道に北面して建つ、ワイン醸造会社の主屋兼事務所。木造二階建、切妻造平入で東に土間を取り、西寄りの床上部は北から西に矩折に縁を廻らす。北西隅の座敷から縁を介して前庭を望む。北面二階に取付く縁と手摺が街路からの景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013093"},{"id":"00013094","register_sub_id":"101","register_pk":"368367","name":"勝沼醸造樽貯蔵庫","kana":"かつぬまじょうぞうたるちょぞうこ","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"昭和中","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎371他","lat":35.65613889,"lng":138.7159,"geo_status":"db","era":"昭和24年頃／平成12年改修","year":1949,"year_source":"db","year_min":1949,"year_max":1949,"year_label":null,"structure":"土蔵造2階建、瓦葺、建築面積44㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0143","desc":"主屋の東に建つ樽貯蔵庫。桁行一三メートル梁間三･六メートルの南北に長い土蔵造二階建。外壁は漆喰仕上で腰壁を人造石洗出しとし、西面に二箇所の扉口を開く。内部は一階二階とも一室で、二階は和小屋を現しとする。主屋兼事務所と並び良質な景観を形作る。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013094"},{"id":"00008859","register_sub_id":"101","register_pk":"162302","name":"旧二葉屋酒造店舗兼主屋","kana":"きゅうふたばやしゅぞうてんぽけんしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"大正","pref":"山梨県","address":"山梨県西八代郡市川三郷町市川大門1170","lat":35.68902778,"lng":138.6885,"geo_status":"db","era":"大正前期","year":1917,"year_source":"estimated","year_min":1912,"year_max":1918,"year_label":"大正前期","structure":"木造2階建、瓦葺、建築面積171㎡","structure_material":"木造2階建","registered":"2011.10.28(平成23.10.28)","register_no":"19 － 0066","desc":"市川大門の市街地、通りから少し入った位置に北面して建つ。木造二階建、寄棟造桟瓦葺、建築面積１７１㎡。東端に土間を通し、中央前方にミセ、後方に台所、西端及び二階に座敷を配し、二階座敷は数寄屋風意匠になる。近代店舗建築の一例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00008859"},{"id":"00013095","register_sub_id":"101","register_pk":"368261","name":"くらむぼんワイン旧主屋","kana":"くらむぼんわいんきゅうしゅおく","category":"産業2次","subcategory":"建築物","type_guess":"主屋","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎字田中835他","lat":35.65551111,"lng":138.723225,"geo_status":"db","era":"明治後期／大正9年移築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建、瓦葺、建築面積165㎡","structure_material":"木造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0144","desc":"敷地中央に南面して建つ。木造二階建、切妻造の東西棟で中央に越屋根を載せる。一階は東に土間を取り、西寄り床上部は二列六室とする。南西隅の座敷には床、棚、付書院を置く。二階は西寄り四室を畳敷とする。養蚕農家の趣を残すワイン醸造家の主屋。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013095"},{"id":"00013096","register_sub_id":"101","register_pk":"368262","name":"くらむぼんワインワインセラー","kana":"くらむぼんわいんわいんせらー","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎字田中835他","lat":35.65562222,"lng":138.723125,"geo_status":"db","era":"明治後期／昭和前期増築、同48年改修","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造2階建一部地階付、金属板葺、建築面積97㎡","structure_material":"木造2階建一部地階付","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0145","desc":"旧主屋の北に東面して建つ。木造二階建の上屋の直下に地下室があり、北寄りの階段を下りて北から入る。建物外の西側にも、もとはブドウ冷蔵庫の地下室があり、周囲の川から水を引き込み上屋の地下に溜めて冷却した。市内でも希少なブドウ冷蔵庫の遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013096"},{"id":"00000044","register_sub_id":"101","register_pk":"101034","name":"葡萄酒貯蔵庫（龍憲セラー）","kana":"ぶどうしゅちょぞうこ（りゅうけんせらー）","category":"産業2次","subcategory":"その他工作物","type_guess":"倉庫","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町下岩崎1856","lat":35.65855909,"lng":138.72111101,"geo_status":"db","era":"明治32頃／大正14改造","year":1899,"year_source":"db","year_min":1899,"year_max":1899,"year_label":null,"structure":"半地下式、前室割石積庫内煉瓦積、建築面積57㎡","structure_material":"半地下式","registered":"1996.12.20(平成8.12.20)","register_no":"19 － 0003","desc":"ヨーロッパの貯蔵技術を導入してつくった我が国最初期の煉瓦造の半地下式葡萄酒貯蔵庫。建設に尽力した土屋龍憲の名をとって「龍憲セラー」の通称をもつ。明治の堅牢な煉瓦積みの技術を用いた建造物で，同様のものを建設することは困難である。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000044"},{"id":"00013091","register_sub_id":"101","register_pk":"368259","name":"丸藤葡萄酒工業旧醸造蔵","kana":"まるふじぶどうしゅこうぎょうきゅうじょうぞうぐら","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"山梨県","address":"山梨県甲州市勝沼町藤井字三口神776他","lat":35.65002222,"lng":138.71495833,"geo_status":"db","era":"明治前期／大正後期増築","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"土蔵造2階建、瓦葺、建築面積56㎡","structure_material":"土蔵造2階建","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0140","desc":"敷地中央に南面して建つ旧醸造蔵。土蔵造二階建、切妻造平入の屋根は置屋根形式とし、北面増築部分にかけて葺下ろす。外壁は漆喰塗で腰を竪羽目板張とする。内部は板敷で壁を漆喰塗とし、小屋組は登梁とする。ワイン醸造の中心施設の一つ。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013091"},{"id":"00013092","register_sub_id":"101","register_pk":"368260","name":"丸藤葡萄酒工業瓶貯蔵庫","kana":"まるふじぶどうしゅこうぎょうびんちょぞうこ","category":"産業2次","subcategory":"その他工作物","type_guess":"倉庫","type_guess_confidence":"low","period":"昭和中","pref":"山梨県","address":"山梨県甲州市勝沼町藤井字三口神776他","lat":35.65005556,"lng":138.71509444,"geo_status":"db","era":"昭和33年／昭和35年増築・平成6年改修","year":1958,"year_source":"db","year_min":1958,"year_max":1958,"year_label":null,"structure":"鉄筋コンクリート造、面積52㎡","structure_material":"鉄筋コンクリート造","registered":"2019.12.05(令和1.12.05)","register_no":"19 － 0141","desc":"敷地東辺に沿って建つ。鉄筋コンクリート造のもとワイン発酵用の貯蔵タンクで、現在は瓶貯蔵庫。細長い折曲がり平面で、内部は南半を五区画、北半を六区画に隔て、各区画の上部に液投入口、下部に排出口を穿つ。当時の醸造過程を伝える希少な遺例。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00013092"},{"id":"00011132","register_sub_id":"101","register_pk":"205239","name":"横山酒造店店舗","kana":"よこやましゅぞうてんてんぽ","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"大正","pref":"山梨県","address":"山梨県南巨摩郡南部町南部8255","lat":35.28971,"lng":138.45565,"geo_status":"db","era":"大正5頃／昭和28頃・同30増築","year":1916,"year_source":"db","year_min":1916,"year_max":1916,"year_label":null,"structure":"木造3階建、瓦葺、建築面積103㎡","structure_material":"木造3階建","registered":"2016.08.01(平成28.08.01)","register_no":"19 - 0082","desc":"街路に挟まれた三角形敷地に建つ店舗兼住宅。当初は二階建であったが道路拡張に伴う縮小や増築を経て三階建となる。外壁は擬石仕上で石造風に見せる。内部造作は和風でまとめるが、天井など一部に洋風の要素を取り入れる。特異な外観が特徴のいわゆる看板建築。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00011132"},{"id":"00000534","register_sub_id":"101","register_pk":"101524","name":"ルミエール旧地下発酵槽","kana":"るみえーるきゅうちかはっこうそう","category":"産業2次","subcategory":"その他工作物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"山梨県","address":"山梨県笛吹市一宮町南野呂624","lat":35.65455898,"lng":138.71129343,"geo_status":"db","era":"明治34","year":1901,"year_source":"db","year_min":1901,"year_max":1901,"year_label":null,"structure":"石造，建築面積203㎡","structure_material":"石造","registered":"1998.04.21(平成10.04.21)","register_no":"19 － 0025","desc":"葡萄酒の発酵タンク及び貯蔵タンクとして作られた。石造半地下式で，幅1.9m，奥行6.6m，高さ2.7mの発酵槽を10基備え，前面を地下通路でつないでいる。現在は上部をコンクリートで塞ぎ，工場が建てられているが，躯体部は堅固で現在も一部が使用されている。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00000534"},{"id":"00005174","register_sub_id":"101","register_pk":"106164","name":"飯田家住宅米蔵","kana":"いいだけじゅうたくこめぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"江戸","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.269344,"lng":137.920776,"geo_status":"db","era":"安政6／明治33増築","year":1859,"year_source":"db","year_min":1859,"year_max":1859,"year_label":null,"structure":"土蔵造平屋建、瓦葺、建築面積119㎡","structure_material":"土蔵造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0242","desc":"敷地の西辺，酛蔵の南に並ぶ土蔵造平屋建である。桁行９間，梁間３間，南北棟で建ち，切妻造，置屋根の桟瓦葺とする。東面の瓦葺庇も垂木を塗上げて置屋根とする。北から４間位置で間仕切り，東面に２箇所の戸口を設ける。西方からの屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005174"},{"id":"00005175","register_sub_id":"101","register_pk":"106165","name":"飯田家住宅醸造蔵一","kana":"いいだけじゅうたくじょうぞうぐらいち","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26949059,"lng":137.92106455,"geo_status":"db","era":"明治後期／昭和初期増築","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積405㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0243","desc":"敷地の北辺中央，酛蔵の東に接続する木造平屋建である。東西棟で，桁行２０間，梁間５間，切妻造，桟瓦葺とする。外壁は大壁造の白漆喰塗で，腰を下見板張とし，北面には竪格子入の窓を配す。小屋組は洋風トラスとする。北方からの屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005175"},{"id":"00005176","register_sub_id":"101","register_pk":"106166","name":"飯田家住宅醸造蔵二","kana":"いいだけじゅうたくじょうぞうぐらに","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26937806,"lng":137.92104479,"geo_status":"db","era":"明治前期","year":1873,"year_source":"estimated","year_min":1868,"year_max":1882,"year_label":"明治前期","structure":"木造平屋建、鉄板葺、建築面積317㎡、煙突付","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0244","desc":"醸造蔵一の南に並ぶ木造平屋建の醸造蔵である。桁行１６間，梁間６間の東西棟で，勾配の緩い切妻屋根は鉄板葺とする。小屋組は和小屋である。外壁は大壁造の白漆喰塗で，腰を下見板張とし，竪格子入小窓を開く。煙突を併設し，東方からの屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005176"},{"id":"00005173","register_sub_id":"101","register_pk":"106163","name":"飯田家住宅酛蔵","kana":"いいだけじゅうたくもとぐら","category":"産業2次","subcategory":"建築物","type_guess":"倉庫","type_guess_confidence":"low","period":"大正","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.2695199,"lng":137.92080296,"geo_status":"db","era":"大正3","year":1914,"year_source":"db","year_min":1914,"year_max":1914,"year_label":null,"structure":"木造2階建、瓦葺、建築面積190㎡","structure_material":"木造2階建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0241","desc":"敷地の北西隅に位置する木造２階建で，東に醸造蔵一が接続する。桁行１０間，梁間５間の南北棟。切妻造，桟瓦葺で東面南半に瓦葺庇がつく。北端３間半を麹室とする。外壁は大壁造の白漆喰塗。小屋組は洋風トラスを採用する。北方からの屋敷景観を形成する。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005173"},{"id":"00005177","register_sub_id":"101","register_pk":"106167","name":"飯田家住宅物置一","kana":"いいだけじゅうたくものおきいち","category":"産業2次","subcategory":"建築物","type_guess":"その他","type_guess_confidence":"low","period":"明治","pref":"長野県","address":"長野県安曇野市豊科高家604-1","lat":36.26919124,"lng":137.92071434,"geo_status":"db","era":"明治後期","year":1901,"year_source":"estimated","year_min":1898,"year_max":1912,"year_label":"明治後期","structure":"木造平屋建、瓦葺、建築面積112㎡","structure_material":"木造平屋建","registered":"2005.12.26(平成17.12.26)","register_no":"20 － 0245","desc":"敷地西辺の中央，米蔵の南に建つ木造平屋建で，もとは酒米の精米に用いられた。桁行７間半，梁間４間で，屋根は切妻造，桟瓦葺とし，小屋組は洋風トラスとする。外壁は真壁造の白漆喰塗で，腰と南妻壁を下見板張りとする。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00005177"},{"id":"00012903","register_sub_id":"101","register_pk":"368006","name":"旧昭和興業製糸場","kana":"きゅうしょうわこうぎょうせいしじょう","category":"産業2次","subcategory":"建築物","type_guess":"工場","type_guess_confidence":"high","period":"大正","pref":"長野県","address":"長野県松本市大字島立字新切2196-1他","lat":36.23153056,"lng":137.93308611,"geo_status":"db","era":"大正14年頃／平成8年移築","year":1925,"year_source":"db","year_min":1925,"year_max":1925,"year_label":null,"structure":"木造平屋建、金属板葺、建築面積175㎡","structure_material":"木造平屋建","registered":"2019.09.10(令和1.09.10)","register_no":"20 － 540","desc":"松本市歴史の里に移築保存した製糸場繰糸所。北正面の木造平屋建、切妻造鉄板葺で、東から揚返場、繰糸場を並べ、正面西端の突出部に煮繭場を設ける。正背面の腰高の連続硝子窓や棟全体に通した越屋根など、近代製糸業の主流であった座繰工場の形式を伝える。","url":"https://kunishitei.bunka.go.jp/heritage/detail/101/00012903"}];
